COLLDATA("tadabburar","ar",[[114,"§المائدة\nwords\nنَكَالًاعُقُوبَةً.\nفِتنَتَهُضَلاَلَتَهُ.\ndeeds\nحدد أسماء قنوات ومواقع عرفت بالصدق لتتابع الأخبار من خلالها، وحدد قنوات عرفت بالكذب ومعاداة الدين، وقاطعها.\nحدد أمورًا يتطهر بها قلبك، ثم افعلها، وتحل بها؛ مثل: حسن الظن، والعفو؛ فإن السعيد من طهر قلبه.\nقل: \"اللهم إني أسألك طهارة قلبي\".\nguid\nتأمل في صورة أهل النار؛ حيث يحاولون الخروج من النار ولا يستطيعون.\nباب التوبة مفتوح؛ حتى مَن ظلَم العباد وآذاهم؛ فإن له توبة إن صدق مع الله ورد المظالم لأهلها.\nالاشتغال بالإصلاح بعد التوبة سبب لقبولها وثباتها.\nrefl\nوَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا\nبدأ الله بالسارق في هذه الآية قبل السارقة، وفي الزنى بالزانية قبل الزاني؛ ما الحكمة في ذلك؟ فالجواب أن يقال: لمَّا كان حب المال على الرجال أغلب، وشهوة الاستمتاع على النساء أغلب؛ بدأ بهما في الموضعين. القرطبي:٧/٤٧٣.\nلماذا قدم الله تعالى ذكر الرجال في السرقة، وقدم ذكر النساء في الزنى؟\nفَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ٣٩\nتوبة السارق هي أن يندم على ما مضى، ويقلع فيما يستقبل، ويردّ ما سرق إلى من يستحقه. ابن جزي:١/٢٣٦.\nما علامات صدق توبة السارق؟\nيَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ\nكان الرسول من شدة حرصه على الخلق يشتد حزنه لمن يظهر الإيمان ثم يرجع إلى الكفر، فأرشده الله تعالى إلى أنه لا يأسى ولا يحزن على أمثال هؤلاء؛ فإن هؤلاء لا في العير، ولا في النفير؛ إن حضروا لم ينفعوا، وإن غابوا لم يفقدوا. السعدي:٢٣١.\nلماذا لا نحزن على المرتد؟\nيَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ\nومعنى المسارعة في الكفر إظهار آثاره عند أدنى مناسبة، وفي كل فرصة، فشبه إظهاره المتكرر بإسراع الماشي إلى الشيء. ابن عاشور:٦/ ١٩٨.\nما معنى المسارعة في الكفر؟\nيَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ\nفدَلَّ ذلك على أن من كان مقصوده بالتحاكم إلى الحكم الشرعي اتباعَ هواه، وأنه إن حُكِم له رضي، وإن لم يحكم له سخط؛ فإن ذلك من عدم طهارة قلبه، كما أن من حاكم وتحاكم إلى الشرع، ورضي به وافق هواه أو خالفه؛ فإنه من طهارة القلب. السعدي:٢٣٢.\nهل كل من تحاكم إلى الشرع يكون مصيبًا في عمله؟ ومن الذي يؤجر على تحاكمه إلى الشرع؟\nوَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ\nودل على أن طهارة القلب سببٌ لكل خير، وهو أكبر داعٍ إلى كل قول رشيد وعمل سديد. السعدي:٢٣٢.\nما أهمية تطهير القلب؟\nلَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ ٤١\n﴿لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٌ﴾ أي: للمنافقين واليهود؛ فخزي المنافقين: الفضيحة وهتك الستر بإظهار نفاقهم، وخزي اليهود: الجزية أو القتل والسبي والنفي، ورؤيتهم من محمد وأصحابه وفيهم ما يكرهون. البغوي ١/٦٧٧.\nكيف يكون خزي المنافقين واليهود في الدنيا؟"],[115,"§المائدة\nwords\nلِلسُّحتِلِلحَرَامِ.\nالمُقسِطِينَالعَادِلِينَ.\nوَالرَبَّانِيُّونَالعُبَّادُ من اليَهُودِ، الَّذِينَ يُرَبُّونَ النَّاسَ بِشَرعِ اللهِ.\nوَالأَحبَارُعُلَمَاءُ اليَهُودِ.\ndeeds\nابتعد اليوم عن القنوات والإذاعات والصحف التي عرفت بالكذب ومحاربة الصالحين.\nسل الله تعالى أن يرزقك القسط والعدل في قولك، وعملك، وحكمك؛ لتنال محبة الله تعالى.\nحدد هدفك من مدارسة كتاب الله بوضوح؛ حتى تجتنب الرياء والسمعة.\nguid\nالعدل واجب مع الجميع؛ حتى مع أعداء الله.\nلا تخشَ الناس في دعوتك إلى الله، بل اخش الله رب الناس.\nأخلص نيتك، ولا تجعل هدفك من حفظ القرآن وفهمه تحصيل مصلحةٍ دنيوية، أو ثناء الناس عليك.\nrefl\nسَمَّٰعُونَ لِلۡكَذِبِ أَكَّٰلُونَ لِلسُّحۡتِۚ\nوسمي المال الحرام سحتًا لأنه يسحت الطاعات؛ أي: يذهبها، ويستأصلها... وقيل: سمي الحرام سحتًا لأنه يسحت مروءة الإنسان. القرطبي:٧/٤٨٥.\nلم سمي المال الحرام سحتًا؟\nسَمَّٰعُونَ لِلۡكَذِبِ أَكَّٰلُونَ لِلسُّحۡتِۚ\nفذكر ما يدخل في آذانهم وقلوبهم من الكلام، وما يدخل في أفواههم وبطونهم من الطعام؛ غذاء الجسوم، وغذاء القلوب؛ فإنهما غذاءان خبيثان: الكذب والسحت. ابن تيمية:٢/٤٧٥-٤٧٦.\nذكر الله تعالى في الآية الكريمة نوعين من الغذاء يتغذى بهما اليهود، فما هما؟\nوَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ\nالربانيون وهم الذين يسوسون الناس بالعلم، ويربونهم بصغاره قبل كباره... قال مجاهد: \"الربانيون فوق العلماء\". القرطبي:٧/٤٩٥.\nكيف يكون المسلم ربانيًا؟\nوَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بَِٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ\n﴿فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنًا قَلِيلًاۚ﴾: فتكتموا الحق، وتظهروا الباطل لأجل متاع الدنيا القليل. وهذه الآفات إذا سلم منها العالم فهو من توفيقه وسعادته؛ بأن يكون همه الاجتهاد في العلم والتعليم، ويعلم أن الله قد استحفظه ما أودعه من العلم، واستشهده عليه، وأن يكون خائفًا من ربه، ولا يمنعه خوف الناس وخشيتهم من القيام بما هو لازم له، وأن لا يؤثر الدنيا على الدين، كما أن علامة شقاوة العالم أن يكون مخلدًا للبطالة، غير قائم بما أمر به، ولا مُبَال بما استحفظ عليه، قد أهمله وأضاعه، قد باع الدين بالدنيا. السعدي:٢٣٣.\nمن خلال هذه الآية وضح الفرق بين العالم الرباني والعالم غير الرباني.\nوَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ\nفالنفس بالنفس وإن كان القاتل رئيسًا مطاعًا من قبيلة شريفة، والمقتول سوقيًّا طارفًا، وكذلك إن كان كبيرًا وهذا صغيرًا، أو هذا غنيًّا وهذا فقيرًا، وهذا عربيًّا وهذا عجميًّا، أو هذا هاشميًّا وهذا قرشيًّا. وهذا رد لما كان عليه أهل الجاهلية. ابن تيمية:٢/٤٨٢.\nلا يتحقق الأمن إلا بتعميم العدل على الجميع، وضح ذلك.\nوَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ\nفجعل الصدقة بالقصاص الواجب على الظالم -وهو العفو عن القصاص- كفارة للعافي، والاقتصاص ليس بكفارة له؛ فعُلِم أن العفو خير له من الاقتصاص؛ وهذا لأن ما أصابه من المصائب مكفِّر للذنوب، ويؤجر العبد على صبره عليها، ويرفع درجته برضاه بما يقضيه الله عليه منها. ابن تيمية:٢/٤٨١.\nالعفو خير من القصاص، وضح ذلك من الآية الكريمة.\nوَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ ٤٤ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ ٤٥ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ٤٧\nولعل وصفهم بالأوصاف الثلاث باعتبارات مختلفة؛ فلإنكارهم ذلك وصفوا بالكافرين، ولوضعهم الحكم في غير موضعه وصفوا بالظالمين، ولخروجهم عن الحق وصفوا بالفاسقين. الألوسي:٦/٤٣٠.\nلماذا وصف الله الحاكمين بغير شرعه بــــ (الكافرين، الظالمين، الفاسقين)؟"],[116,"§المائدة\nwords\nوَقَفَّينَاأَتبَعنَا.\nوَمُهَيمِنًا عَلَيهِحَاكِمًا عَلَيهَا، شَاهِدًا بِصِحَّتِهَا، أَمِينًا عَلَيهَا.\nشِرعَةً وَمِنهَاجًاشَرِيعَةً، وَطَرِيقًا وَاضِحًا فِي الدِّينِ.\nلِيَبلُوَكُملِيَختَبِرَكُم.\ndeeds\nاسبق اليوم غيرك إلى نوع من الطاعات؛ كالصف الأول، والصدقة لمضطر محتاج، أو غيرها من أبواب الخير.\nبادر بالتخلي عن صديق يصدك عن ذكر الله، واستبدل به من يقربك من الله؛ فإن من ترك شيئًا لله عوضه الله خيرًا منه.\nأرسل رسالة تربط فيها بين عقوبة حلت بالمجتمع وذنب انتشر فيه.\nguid\nالشريعة ابتلاءٌ من الله -سبحانه وتعالى- لعباده؛ ليرى من يستجيب ومن لا يستجيب.\nعمرك قصير؛ فاستبق الخيرات.\nاحذر الوسائل التي تقنعك بقيم اليهود والنصارى وأفكارهم؛ فإن الله -عز وجل- قد حَذَّر نبيه من أن يفتنوه، فكيف بمن هو دونه؟!\nrefl\nوَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ٤٦\nما ذكره من مدح المسيح والإنجيل ليس فيه مدح النصارى الذين كذبوا محمدًا -صلى الله عليه وسلم-، وبدّلوا أحكام التوراة والإنجيل، واتبعوا المبدّل المنسوخ. ابن تيمية:٢/٤٨٥.\nهل الثناء على عيسى -عليه السلام- ومدح الإنجيل فيه مدح للنصارى المعاصرين؟\nوَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ\n﴿وَمُهَيۡمِنًا عَلَيۡهِۖ﴾ أي: مشتملًا على ما اشتملت عليه الكتب السابقة وزيادة في المطالب الإلهية والأخلاق النفسية؛ فهو الكتاب الذي تتبع كل حق جاءت به الكتب فأمر به، وحث عليه، وأكثر من الطرق الموصلة إليه، وهو الكتاب الذي فيه نبأ السابقين واللاحقين، وهو الكتاب الذي فيه الحكم والحكمة. السعدي:٢٣٤.\nكيف كان القرآن مهيمنًا على الكتب السابقة؟\nفَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ\nوهذا يدل على أن تقديم الواجبات أفضل من تأخيرها، وذلك لا خلاف فيه. القرطبي:٨/٣٩.\nهل المسارعة لتأدية الواجبات أفضل، أم تأخيرها أفضل؟\nفَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ\nويستدل بهذه الآية على المبادرة لأداء الصلاة وغيرها في أول وقتها، وعلى أنه ينبغي أن لا يقتصر العبد على مجرد ما يجزئ في الصلاة وغيرها من العبادات من الأمور الواجبة، بل ينبغي أن يأتي بالمستحبات التي يقدر عليها لتتم وتكمل، ويحصل بها السبق. السعدي:٢٣٤.\nكيف يكون العبد سابقًا في الخيرات؟\nوَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ\nفقد نهاه عن اتباع أهواء المشركين، واتباع أهواء أهل الكتاب، وحذره أن يفتنوه عمَّا أنزل الله إليه من الحق، وذلك يتضمن النهي عن اتباع أهواء أحد في خلاف شريعته وسنته، وكذا أهل الأهواء من هذه الأمة. ابن تيمية:٢/٤٩٤.\nفي الآية توجيه مهم لكل مسؤول فما هو؟\nوَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ\nأي: آراءهم التي اصطلحوا عليها، وتركوا بسببها ما أنزل الله على رسله، ولهذا قال تعالى: ﴿وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ﴾ أي: لا تنصرف عن الحق الذي أمرك الله به إلى أهواء هؤلاء الجهلة الأشقياء. ابن كثير:٢/٦٣.\nما البديل عن حكم الله في زعم الجهلة والأشقياء؟\nوَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ\nأي: واحذر أعداءك اليهود أن يدلسوا عليك الحق فيما ينهونه إليك من أمور، فلا تغتر بهم؛ فإنهم كذبة كفرة خونة، ابن كثير:٢/٦٤.\nاسترشاد المسلمين بآراء اليهود والنصارى ونصائحهم كثيرًا ما يكون سببًا لمصائب المسلمين، وضح ذلك من الآية."],[117,"§المائدة\nwords\nيُسَارِعُونَ فِيهِميُبَادِرُونَ فِي مَوَدَّةِ اليَهُودِ ونَحوِهِم.\nدَائِرَةٌنَائِبَةٌ وَمُصِيبَةٌ تَدُورُ عَلَينَا.\nجَهدَ أَيمَانِهِممُجتَهِدِينَ فِي الحَلِفِ بِأَوكَدِ الأَيمَانِ.\nحَبِطَتبَطَلَت.\nأَذِلَّةٍرُحَمَاءَ.\nلَومَةَ لاَئِمٍاعتِرَاضَ مُعتَرِضٍ.\ndeeds\nأكثر اليوم من سؤال الله تعالى أن يطهر قلبك ويصلحه.\nاهد هدية، أو زر أخًا لك في الله أصغر منك سنًا، أو أقل منك قدرًا.\nأرسل رسالة تحث فيها على مقاطعة من يسخر من دين الله.\nguid\nالمؤمن لا يوالي غير المؤمن، ومن فعل ذلك ففي إيمانه ضعف.\nمن سمات مرضى القلوب مسارعتهم في أعداء الدين لإرضائهم، ونيل محبتهم.\nعلى المؤمن أن يكون فطِنًا، ويعرف أعداءه من أصدقائه من خلال أقوالهم وأفعالهم، ولا يكتفي بمجرد الدعوى، والأيمان والحلف.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥١\nعرف أهل الخبرة أن أهل الذمة من اليهود والنصارى والمنافقين يكاتبون أهل دينهم بأخبار المسلمين، وبما يطلعون على ذلك من أسرارهم؛ حتى أُخذ جماعة من المسلمين في بلاد التتار وسُبي وغير ذلك بمطالعة أهل الذمة لأهل دينهم. ابن تيمية:٢/٤٩٦.\nلماذا جاء النهي عن موالاة أهل الكتاب؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥١\nوأصل الموالاة هي المحبة، كما أن أصل المعاداة البغض؛ فإن التحاب يوجب التقارب والاتفاق، والتباغض يوجب التباعد والاختلاف. ابن تيمية:٢/٤٩٨.\nما أصل الموالاة؟ وما أصل المعاداة؟\nفَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ٥٢\n﴿فِي قُلُوبِهِم مَّرَضٌ﴾ أي: شك ونفاق، وضعف إيمان؛ يقولون: إنَّ تولينا إياهم للحاجة؛ فإننا ﴿نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌۚ﴾ أي: تكون الدائرة لليهود والنصارى، فإذا كانت الدائرة لهم فإذا لنا معهم يد يكافئوننا عنها. وهذا سوء ظن منهم بالإسلام؛ قال تعالى رادًّا لظنهم السيئ: ﴿فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ﴾ الذي يعز الله به الإسلام. السعدي:٢٣٥.\nوضح من خلال الآية كيف يؤدي سوء الظن إلى منكر عظيم.\nفَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ٥٢\n(نادمين) أي: على ما كان منهم مما لم يُجدِ عنهم شيئًا، ولا دفع عنهم محذورًا، بل كان عين المفسدة؛ فإنهم فُضحوا، وأظهر الله أمرهم في الدنيا لعباده المؤمنين، بعد أن كانوا مستورين لا يُدرى كيف حالهم، فلما انعقدت الأسباب الفاضحة لهم تبين أمرهم لعباد الله المؤمنين، فتعجبوا منهم كيف كانوا يظهرون أنهم من المؤمنين، ويحلفون على ذلك ويتأولون، فبان كذبهم، وافتراؤهم. ابن كثير:٢/٦٦.\nمن يؤثِر موالاة الكافرين على حساب المسلمين فقد يعاقب في الدنيا قبل الآخرة، وضح ذلك.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ\n(أذلة) وهو جمع ذليل؛ ولما كان ذلهم هذا إنَّما هو: الرِّفق ولين الجانب لا الهَوَان، كان في الحقيقة عزًّا. البقاعي:٢/٤٨٣.\nما المقصود بالذلة للمؤمنين في الآية الكريمة؟\nأَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ\nفالغلظة والشدة على أعداء الله مما يقرب العبد إلى الله، ويوافق العبد ربه في سخطه عليهم، ولا تمنع الغلظةُ عليهم والشدةُ دعوتَهم إلى الدين الإسلامي بالتي هي أحسن؛ فتجتمع الغلظة عليهم واللين في دعوتهم، وكلا الأمرين في مصلحتهم، ونفعه عائد إليهم. السعدي:٢٣٦.\nمتى نغلظ على الكافرين، ومتى نلين معهم؟\nذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ٥٤\nولما مدحهم تعالى بما مَنَّ به عليهم من الصفات الجليلة، والمناقب العالية، المستلزمة لما لم يُذكر من أفعال الخير؛ أخبر أن هذا من فضله عليهم وإحسانه؛ لئلَّا يُعجبوا بأنفسهم، وليشكروا الذي مَنَّ عليهم بذلك؛ ليزيدهم من فضله، وليعلم غيرُهم أن فضل الله تعالى ليس عليه حجاب. السعدي:٢٣٦.\nلماذا خَتَم الله صفات المؤمنين بأنها من فضله؟"],[118,"§المائدة\nwords\nمَثُوبَةًجَزَاءً، وَعُقُوبَةً.\nالطَّاغُوتَكُلَّ مَن عُبِدَ مِن دُونِ اللهِ.\nالسُّحتَالحَرَامَ؛ وَمِنهُ الرِّشوَةُ وَالرِّبَا.\nمَغلُولَةٌمَحبُوسَةٌ عَن فِعلِ الخَيرِ.\ndeeds\nإذا سمعت الأذان فقل مثلما يقول المؤذن، ثم صل على نبيك -صلى الله عليه وسلم-، واسأل ربك من فضله.\nاذهب اليوم إلى المسجد بعد الأذان مباشرة.\nبأسلوب حسن أرسل رسالة تنصح فيها التجار أن يتحرزوا من أكل الحرام، وأكل أموال الناس بالباطل.\nguid\nالمستهزئ بالدين وشعائره لا عقل له.\nسبب كُره اليهود والنصارى للمسلمين أن المسلمين آمنوا بتوحيد الله وبجميع الرسل والكتب.\nأكثر أهل الكتاب موصوفون بالفسق؛ فلا تُعجَب بأقوالهم، ولا بأفعالهم.\nrefl\nوَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ٥٨\nما كان عليه المشركون والكفار المخالفون للمسلمين من قدحهم في دين المسلمين، واتخاذهم إياه هزوًا ولعبًا، واحتقاره واستصغاره، خصوصًا الصلاة التي هي أظهر شعائر المسلمين، وأجل عباداتهم، أنهم إذا نادوا إليها اتخذوها هزوًا ولعبًا؛ وذلك لعدم عقلهم، ولجهلهم العظيم، وإلا فلو كان لهم عقول لخضعوا لها، ولعلموا أنها أكبر من جميع الفضائل التي تتصف بها النفوس. السعدي:٢٣٧.\nعلى ماذا يدل احتقار الشعائر الدينية والاستهزاء بها؟\nوَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ٥٨\nجعل قلة عقولهم علة لاستهزائهم بالدين. ابن جزي:١/٢٤٢.\nماذا تستفيد من هذه الآية؟\nوَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ٥٨\nوقوله: ﴿ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٌ لَّا يَعۡقِلُونَ﴾ تحقيرٌ لهم؛ إذ ليس في النداء إلى الصلاة ما يوجب الاستهزاء، فجعله موجبًا للاستهزاء سخافةً لعقولهم. ابن عاشور:٦/٢٤٢.\nشأن الأذان والصلاة عند الله عظيم، وضح ذلك من الآية.\nقُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ ٥٩\nفأولى لكم أيها الفاسقون السكوت، فلو كان عيبكم وأنتم سالمون من الفسق -وهيهات ذلك- لكان الشر أخف من قدحكم فينا مع فسقكم. السعدي:٢٣٧.\nبينت الآية أن من علامة السفاهة أن يجمع الإنسان بين صفتين، فما هما؟\nلَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ ٦٣\nودلت الآية على أن تارك النهي عن المنكر كمرتكب المنكر؛ فالآية توبيخ للعلماء في ترك الأمر بالمعروف والنهي عن المنكر. القرطبي:٨/٨١.\nالعلم وحده لا يكفي، فما المطلوب معه؟\nوَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ\nلو عامل الله اليهود القائلين تلك المقالة ونحوهم ممن حاله كحالهم ببعض قولهم لهلكوا، وشقوا في دنياهم، ولكنهم يقولون تلك الأقوال وهو تعالى يحلم عنهم، ويصفح، ويمهلهم ولا يهملهم. السعدي:٢٣٨.\nكيف تستدل بهذه الآية على سعة رحمة الله سبحانه؟\nكُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ٦٤\nإيقاد النار عبارة عن محاولة الحرب، وإطفاؤها عبارة عن خذلانهم وعدم نصرهم، ويحتمل أن يراد بذلك أسلافهم، أو يراد من كان معاصرًا للنبي -صلّى الله عليه وعلى آله وسلّم- منهم، ومن يأتي بعدهم، فيكون على هذا إخبار بغيب، وبشارة للمسلمين. ابن جزي:١/٢٤٤.\nاذكر باختصار موقفًا من خذلان الله لليهود زمن النبوة، وموقفًا من خذلان الله لهم في زمننا المعاصر."],[119,"§المائدة\nwords\nمُقتَصِدَةٌمُعتَدِلَةٌ، ثَابِتَةٌ عَلَى الحَقِّ.\nتُقِيمُواتَعمَلُوا.\nوَالصَّابِئُونَقَومٌ بَاقُونَ عَلَى فِطرَتِهِم، وَلَا دِينَ لَهُم يَتَّبِعُونَهُ.\ndeeds\nعدد بعض أسباب الرزق الواردة في القرآن، ثم أرسلها في رسالة لمن حولك.\nحذر من منكر أو قدم نصيحة أو بيِّن علمًا، وليكن بلاغك بالحكمة والبيان الحسن.\nتذكر آية تحفظها وأنت مخالف لها، ثم طبق ما أمر الله به فيها على نفسك.\nguid\nلو أقمت الدين على أكمل وجهٍ لرزقك الله من خيري الدنيا والآخرة.\nاعلم أن الله تعالى عاصم أولياءه مما يخافون ويحذرون، فتوكل على الله تعالى حتى يحفظك من كل مكروه.\nالإيمان لا يكون صادقًا إلا إذا آمن الرجل بما تهواه نفسه وما تكرهه، أما الإيمان بما تهواه النفس ورد ما لا تهواه فهو عبادة للهوى.\nrefl\nوَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَئَِّاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّٰتِ ٱلنَّعِيمِ ٦٥\nوهذا من كرمه وجوده؛ حيث ذكر قبائح أهل الكتاب، ومعايبهم، وأقوالهم الباطلة؛ دعاهم إلى التوبة، وأنهم لو آمنوا بالله وملائكته وجميع كتبه وجميع رسله، واتقوا المعاصي لكفَّر عنهم سيئاتهم ولو كانت ما كانت، ولأدخلهم جنات النعيم. السعدي:٢٣٨.\nالآية تفتح باب الرجاء للعصاة من أمة محمد -صلى الله عليه وسلم-، وضح ذلك.\nوَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ\n(ولَو أَنهم أَقاموا التوراةَ والإنجيل): إقامتها بالعلم والعمل. ابن جزي:١/٢٤٤.\nإقامة كتاب الله بأمرين، فما هما؟\nوَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ\n﴿لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ﴾: قال ابن عباس وغيره: \"يعني المطر والنبات\"، وهذا يدل على أنهم كانوا في جدب، وقيل: المعنى لوسّعنا عليهم في أرزاقهم، ولأكلوا أكلًا متواصلًا، وذكر فوق وتحت للمبالغة فيما يفتح عليهم من الدنيا، ونظير هذه الآية: ﴿وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ٢ وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُ﴾ [الطلاق: ٢-٣]. القرطبي:٨/٨٨.\nما علاج الفقر وضيق الرزق المذكور في الآية؟\nوَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ ٦٦\nوقد أومأت الآية إلى أن سبب ضيق معاش اليهود هو من غضب الله تعالى عليهم؛ لإضاعتهم التوراة، وكفرهم بالإنجيل وبالقرآن؛ أي: فتحتمت عليهم النقمة بعد نزول القرآن. ابن عاشور:٦/٢٥٣.\nغضب الله تعالى على عبده موجب لضيق الرزق، دلل لذلك من الآية الكريمة.\n۞يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ٦٧\nفهي أقطع آية لإبطال قول الرافضة بأن القرآن أكثر مما هو في المصحف الذي جمعه أبو بكر ونسخه عثمان، وأن رسول الله اختص بكثير من القرآن عليًّا بن أبي طالب، وأنه أورثه أبناءه، وأنه يبلغ وقر بعير، وأنه اليوم مختزن عند الإمام المعصوم الذي يلقبه بعض الشيعة بالمهدي المنتظر وبالوصي. ابن عاشور:٦/٢٦٠.\nكيف كانت الآية الكريمة ردًا على قول الرافضة بنقص القرآن الكريم؟\nيَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ\nأخبر أنه ليس ينطق من عنده، بل يتكلم بكل ما يسمع، وهذا إخبار بأن كل ما يتكلم به فهو وحي يسمعه، ليس هو شيئًا تعلمه من الناس، أو عرفه باستنباطه. ابن تيمية:٢/٥٠٧.\nالسنة وحي من الله تعالى، كيف دلت الآية الكريمة على ذلك؟\nيَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ٦٧\nأي: ليس عليك إلا البلاغ، فلا يحزُنك مَن لا يَقبَل، فليس إعراضه لقصور في إبلاغك ولا حظك، بل لقصور إدراكه وحظه؛ لأن الله حتم بكفره، وختم على قلبه لما علم من فساد طبعه، والله لا يهدي مثله. البقاعي:٢/٥٠٣.\nاذكر المعنى الإجمالي للآية. فقهك الله في دينه."],[120,"§المائدة\nwords\nفِتنَةٌعَذَابٌ، وَبَلاَءٌ.\nصِدِّيقَةٌقَد صَدَّقَت تَصدِيقًا جَازِمًا.\nلاَ تَغلُوالاَ تَتَجَاوَزُوا الحَقَّ فِي اعتِقَادِكُم.\ndeeds\nأرسل رسالة تبين فيها أن الله سبحانه قد يغفر كل ذنب إلا الشرك.\nجدد توبتك لله تعالى، وليكن يومك هذا بداية ترك لمعصية كنت مترددًا في تركها.\nاستغفر الله تعالى هذا اليوم سبعين مرة.\nguid\nاعلم أن الغرور وطول الأمل يصدان العبد عن طريق الله تعالى؛ فاحذر ذلك.\nاحذر الشرك؛ فإنه لا تنفع معه طاعة.\nلا بأس عند مجادلة غير المسلمين من استعمال الأدلة العقلية التي تدل على بطلان ما يفعلونه.\nrefl\nوَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ٧١\nظن هؤلاء الذين أخذ عليهم الميثاق أنه لا يقع من الله -عز وجل- ابتلاء واختبار بالشدائد؛ اغترارًا بقولهم: نحن أبناء الله وأحباؤه، وإنَّما اغتروا بطول الإمهال. القرطبي:٨/٩٧.\nبأي شيء اغتروا حتى تركوا امتثال أمر الله تعالى؟\nوَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ٧١\n﴿تَابَ ٱللَّهُ عَلَيۡهِمۡ﴾ أي: رجع بهم إلى الطاعة والحق، ومن فصاحة اللفظ استناد هذا الفعل الشريف إلى الله تعالى، واستناد العمى والصمم اللذين هما عبارة عن الضلال إليهم. ابن عطية:٢/٢٢١.\nهذه الآية تبين لطف الله تعالى بعباده، وجهل عباده بمصلحتهم، وضح ذلك.\nلَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ\nيخبر تعالى عن كفر النصارى بقولهم: ﴿إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ﴾ بشبهة أنه خرج من أم بلا أب، وخالف المعهود من الخلقة الإلهية، والحال أنه -عليه الصلاة والسلام- قد كذّبهم في هذه الدعوى، وقال لهم: (يَا بَنِي إِسرَائِيلَ اعبُدُوا اللَّهَ رَبِّي وَرَبَّكُم)؛ فأثبت لنفسه العبودية التامة، ولربه الربوبية الشاملة لكل مخلوق. السعدي:٢٤٠.\nلماذا ذكر قول عيسى بعد ذكر قول النصارى؟\nأَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٧٤\n﴿أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ﴾: فالتوبة هي الإقلاع عما هو عليه في المستقبل، والرجوع إلى الاعتقاد الحق، والاستغفار: طلب مغفرة ما سلف منهم في الماضي، والندم عما فرط منهم من سوء الاعتقاد. ابن عاشور:٦/٢٨٤.\nلماذا جمع بين التوبة والاستغفار في الآية الكريمة ؟\nأَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٧٤\nيغفر ذنوب التائبين، ولو بلغت عنان السماء، ويرحمهم بقبول توبتهم، وتبديل سيئاتهم حسنات. وصدّر دعوتهم إلى التوبة بالعرض الذي هو غاية اللطف واللين في قوله: ﴿أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ﴾. السعدي:٢٤٠.\nكيف يفيد الداعية من هذه الآية في دعوته؟\nمَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ\n(صديقة) أي: كثيرة الصدق، وقيل: سميت صديقة لأنها صدقت بآيات الله؛ كما قال -عز وجل- في وصفها: ﴿وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا﴾ [التحريم: ١٢]. البغوي:١/٦٩٩.\nلماذا وصفت مريم -عليها السلام- بالصديقة؟\nمَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ\nدليل ظاهر على أنهما عبدان فقيران، محتاجان -كما يحتاج بنو آدم- إلى الطعام والشراب، فلو كانا إلهين لاستغنيا عن الطعام والشراب، ولم يحتاجا إلى شيء؛ فإن الإله هو الغني الحميد. السعدي:٢٤٠.\nكيف يستدل بأكل الطعام على عدم ألوهية عيسى وأمه؟"],[121,"§المائدة\nwords\nقِسِّيسِينَعُلَمَاءَ النَّصَارَى.\nوَرُهبَانًاعُبَّادَ النَّصَارَى.\nتَفِيضُتَمتَلِئُ دَمعًا، فَيَنسَكِبُ.\ndeeds\nاشكر أحد الآمرين بالمعروف والناهين عن المنكر، وادع له بالتوفيق ولو برسالة.\nبحكمة ورحمة أنكر اليوم منكرًا من غيبة تسمعها، أو نميمة تصل إليك، أو نحو ذلك.\nتواضع للناس بمد يد العون لهم هذا اليوم، واختيار الكلمة الطيبة، والإحسان إلى ضعيف أو مسكين.\nguid\nالعصيان والاعتداء يجلبان لصاحبهما الحرمان والخسران.\nالأمر بالمعروف والنهي عن المنكر من مقومات الدين العظيمة، وترك بعض الأمم لها كان سببًا للعنها.\nتولي الذين كـفروا من الأمـور التي تسـبب سـخط الله على العبد.\nrefl\nلُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ٧٨\nلم ينفعهم -مع نسبتهم إلى واحدة من الشريعتين- نسبتهم إلى إسرائيل -عليه السلام-؛ فإنه لا نسب لأحد عند الله دون التقوى، لا سيما في يوم الفصل؛ إذ الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين. البقاعي:٢/٥١٨.\nإسرائيل نبي من أنبياء الله، ومع ذلك لُعِن من كفر من ذريته، فهل ينفع النسب الشريف بلا عبادة؟ وضح ذلك.\nكَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ ٧٩\nقال حذاق أهل العلم: ليس من شرط الناهي أن يكون سليمًا عن معصية، بل ينهى العصاة بعضهم بعضًا. القرطبي: ٨/١٠٦.\nهل من شرط الناهي عن المنكر أن يكون سليمًا من المعاصي؟ وضح ذلك.\nوَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ\nبين سبحانه أن الإيمان له لوازم وله أضداد موجودة؛ يستلزم ثبوت لوازمه وانتفاء أضداده، ومن أضداده مُوادّة من حادّ الله ورسوله. ابن تيمية:٢/٥٢١.\nذكرت الآية الكريمة أحد أضداد الإيمان، فما هو؟\nوَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ\nلم يرد به جميع النصارى؛ لأنهم في عداوتهم المسلمين كاليهود؛ في: قتلهم المسلمين، وأسرهم، وتخريب بلادهم، وهدم مساجدهم، وإحراق مصاحفهم؛ لا ولاء ولا كرامة لهم، بل الآية فيمن أسلم منهم. البغوي:١/٧٠٢.\nمن المقصود بالنصارى المذكورين في الآية؟\nذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا\n﴿قِسِّيسِينَ وَرُهۡبَانًا﴾ أي: علماءً متزهدين، وعبادًا في الصوامع متعبدين. والعلم مع الزهد، وكذلك العبادة، مما يلطف القلب ويرققه، ويزيل عنه ما فيه من الجفاء والغلظة؛ فلذلك لا يوجد فيهم غلظة اليهود، وشدة المشركين. السعدي:٢٤٢.\nلرقة القلب أسباب، فما هي؟\nوَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ ٨٣\nوهذه أحوال العلماء: يبكون ولا يصعقون، ويسألون ولا يصيحون، ويتحازنون ولا يتموتون؛ كما قال تعالى: ﴿ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِ﴾ [الزمر: ٢٣]. القرطبي:٨/١١٣.\nكيف يكون التأثر الشرعي بكتاب الله تعالى؟\nوَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ ٨٣\n﴿فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ﴾ قال ابن عباس: مع محمد -صلى الله عليه وسلم- وأمته؛ وهم الأمة الشهداء؛ فإن النصارى لهم قصد وعبادة، وليس لهم علم وشهادة. ابن تيمية:٢/٥٢٢.\nما المراد بقوله تعالى: ﴿فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ﴾؟"],[122,"§المائدة\nwords\nوَالمَيسِرُالقِمَارُ، وَهُوَ المُرَاهَنَاتُ الَّتِي فِيهَا عِوَضٌ مِنَ الجَانِبَينِ.\nوَالأَنصَابُحِجَارَةٌ كَانَ المُشرِكُونَ يَذبَحُونَ عِندَهَا تَعظِيمًا.\nوَالأَزلاَمُالقِدَاحُ الَّتِي يَستَقسِمُ بِهَا الكُفَّارُ قَبلَ الإِقدَامِ عَلَى الشَّيءِ، أَوِ الإِحجَامِ عَنهُ؛ يَكتُبُونَ عَلَى أحَدِهَا: (افعَل)، وَعَلَى الآخَرِ: (لاَ تَفعَل)، ثُمَّ يُحَرِّكُونَهَا فَأَيُّهَا خَرَجَ، عَمِلُوا بِهِ.\nرِجسٌإِثمٌ.\ndeeds\nابحث عن جلساء صالحين، وحاول الدخول معهم.\nإذا لم تستطع اليوم أن تفعل الخير بمالك أو بيدك، فاختر قولًا جميلًا تقوله بلسانك، تؤجر عليه أجرًا عظيمًا.\nحذر الناس من طعام حرام تساهلوا فيه، وذكرهم ببديل من الحلال الطيب.\nguid\nكن حسن الظن بالله دائم الطمع في رحمته.\nاجعل مطعمك من الحلال.\nاحفظ لسانك عن كثرة الحلِف.\nrefl\nفَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ ٨٥\n﴿فَأَثَٰبَهُمُ ٱللَّهُ﴾: أعطاهم الله، ﴿بِمَا قَالُواْ جَنَّٰتٍ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ﴾: وإنَّما أنجح قولهم، وعلق الثواب بالقول لاقترانه بالإخلاص؛ بدليل قوله: ﴿وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ﴾ يعني: الموحدين المؤمنين. البغوي:٢/٧٠٤.\nلماذا أثابهم الله تعالى هذا الجزاء العظيم على قولهم؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ\n﴿وَلَا تَعۡتَدُوٓاْۚ﴾: ...كما لا تحرموا الحلال، فلا تعتدوا في تناول الحلال، بل خذوا منه بقدر كفايتكم وحاجتكم، ولا تجاوزوا الحد فيه... فشرع الله عدلٌ بين الغالي فيه والجافي عنه؛ لا إفراط ولا تفريط. ابن كثير:٢/٨٤.\nكيف تدل هذه الآية على الوسطية في الدين؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٨٧\nولهذا ينكر على من يتقرب إلى الله بترك جنس اللذات؛ كما قال -صلى الله عليه وسلم- للذين قال أحدهم: أما أنا فأصوم لا أفطر، وقال الآخر: أما أنا فأقوم لا أنام، وقال الآخر: أما أنا فلا أتزوج النساء، وقال الآخر: أما أنا فلا آكل اللحم، فقال النبي -صلى الله عليه وسلم-: «لكني أصوم وأفطر، وأقوم وأنام، وأتزوج النساء، وآكل اللحم؛ فمن رغب عن سنتي فليس مني». ابن تيمية:٢/٥٢٤.\nما حكم من يتقرب إلى الله تعالى بترك جنس اللذات؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٨٧\nيعني بـالطيبات: اللذيذات التي تشتهيها النفوس، وتميل إليها القلوب، فتمنعوها إياها؛ كالذي فعله القسيسون والرهبان، فحرموا على أنفسهم النساء، والمطاعم الطيبة، والمشارب اللذيذة، وحبس في الصوامع بعضهم أنفسهم، وساح في الأرض بعضهم. يقول تعالى ذكره: فلا تفعلوا -أيها المؤمنون- كما فعل أولئك، ولا تعتدوا حد الله الذي حد لكم فيما أحل لكم وفيما حرم عليكم، فتجاوزوا حده الذي حده، فتخالفوا بذلك طاعته؛ فإن الله لا يحب من اعتدى حده الذي حده لخلقه فيما أحل لهم وحرم عليهم. الطبري:١٠/٥١٣.\nكيف يكون الاعتداء في باب المباحات من أكل، وشرب، ونكاح؟\nوَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ\nأي: كلوا من رزقه الذي ساقه إليكم بما يسره من الأسباب إذا كان حلالًا؛ لا سرقة، ولا غصبًا، ولا غير ذلك من أنواع الأموال التي تؤخذ بغير حق. وكان أيضًا طيبًا؛ وهو الذي لا خبث فيه، فخرج بذلك الخبيث من السباع والخبائث. السعدي:٢٤٢.\nيجب أن يتوفر في المطعومات المباحة شرطان، فما هما؟\nفَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ\nهذه خصال ثلاث في كفارة اليمين؛ أيها فعل الحانث أجزأ عنه بالإجماع، وقد بدأ بالأسهل، فالأسهل؛ فالإطعام أسهل وأيسر من الكسوة، كما أن الكسوة أيسر من العتق، فترقى فيها من الأدنى إلى الأعلى، فإن لم يقدر المكلف على واحدة من هذه الخصال الثلاث كفر بصيام ثلاثة أيام؛ كما قال تعالى: ﴿فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ﴾. ابن كثير:٢/٨٦.\nما الحكمة في ترتيب خصال الكفارة على هذا الترتيب؟\nفَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ ٩٠\nالفلاح لا يتم إلا بترك ما حرم الله، خصوصًا هذه الفواحش المذكورة، وهي الخمر؛ وهي: كل ما خامر العقل، أي: غطاه بسكره، والميسر، وهو: جميع المغالبات التي فيها عوض من الجانبين، كالمراهنة ونحوها. السعدي:٢٤٣.\nبما يحصل فلاح الإنسان؟"],[123,"§المائدة\nwords\nجُنَاحٌحَرَجٌ، وَإِثمٌ.\nحُرُمٌمُحرِمُونَ.\nالنَّعَمِبَهِـيمَةِ الأَنعَامِ؛ مِنَ الإِبِلِ وَالبَقَرِ وَالغَنَمِ.\nبَالِغَ الكَعبَةِيَصِلُ لِفُقَرَاءِ الحَرَمِ.\nوَبَالَ أَمرِهِعَاقِبَةَ فِعلِهِ.\ndeeds\nتأمل اثنين من طرق الشيطان في إضلال بني آدم من خلال هذه الآيات.\nابحث عن شيء يشغلك عن ذكر الله و عن الصلاة، واتركه لله؛ لعل الله يعوضك خيرًا منه.\nأرسل رسالة تحذر فيها من طعام محرم تساهل الناس في أكله.\nguid\nشرب الخمر يثير العداوة والبغضاء بين الشاربين واللاعبين، ويصد عن ذكر الله، وعن الصلاة.\nالحذر من معصية الله والرسول -صلى الله عليه وسلم-.\nالخوف من الله في حال الغيب عن الناس له شأن عظيم عند الله.\nrefl\nإِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ ٩١\nثم أعلم تعالى عباده أن الشيطان إنَّما يريد أن تقع العداوة بسبب الخمر، وما كان يغري عليها بين المؤمنين، وبسبب الميسر؛ إذ كانوا يتقامرون على الأموال والأهل، حتى ربما بقي المقمور حزينًا فقيرًا؛ فتحدث من ذلك ضغائن وعداوة، فإن لم يصل الأمر إلى حد العداوة، كانت بغضاء، ولا تحسن عاقبة قوم متباغضين. ابن عطية:٢/٢٣٤.\nكيف نفهم أن هذه الأشياء المذكورة في الآية تفرق المجتمع، وتفقد الأمن؟\nإِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ\nفإن في الخمر من انغلاق العقل، وذهاب حجاه، ما يدعو إلى البغضاء بينه وبين إخوانه المؤمنين؛ خصوصًا إذا اقترن بذلك من السباب ما هو من لوازم شرب الخمر؛ فإنه ربما أوصل إلى القتل. وما في الميسر من غلبة أحدهما للآخر، وأخذ ماله الكثير في غير مقابلة، ما هو من أكبر الأسباب للعداوة والبغضاء. السعدي:٢٤٣.\nكيف تحصل العداوة والبغضاء بين متعاطي الخمر والميسر؟\nإِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ ٩١\nفكل لهو دعا قليله إلى كثيره، وأوقع العداوة والبغضاء بين العاكفين عليه، وصد عن ذكر الله، وعن الصلاة، فهو كشرب الخمر. القرطبي:٨/١٦٥.\nما علامات اللهو الحرام؟\nلَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ\nومما يدل على نفاسة التقوى وعزتها أنه سبحانه لمَّا شرطها في هذا العموم؛ حثَّ عليها عند ذكر المأكل بالخصوص... وهذا في غاية الحث على التورع في المأكل والمشرب، وإشارة إلى أنه لا يوصل إلى مقام الإحسان إلا به. البقاعي:٢/٥٣٩.\nما مدى ارتباط الطعام والشراب بالوصول إلى مرتبة الإحسان التي هي أعلى المراتب؟\nلَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ٩٣\n﴿ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾: دليل على أن المتقي المحسن أفضل من المتقي المؤمن. القرطبي ٨/١٧٢.\nبيّن ما يدل على فضل أهل الإحسان من الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ\n(الغيب): ضد الحضور، وضد المشاهدة... وفائدة ذكره أنه ثناء على الذين يخافون الله؛ أثنى عليهم بصدق الإيمان وتنور البصيرة؛ فإنهم خافوه ولم يروا عظمته وجلاله ونعيمه وثوابه، ولكنهم أيقنوا بذلك عن صدق استدلال. ابن عاشور:٧/٤٠.\nما فائدة ذكر كلمة (بالغيب) في الآية الكريمة؟\nلِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ\nوالاعتبار بمن يخافه بالغيب وعدم حضور الناس عنده، وأمَّا إظهار مخافة الله عند الناس فقد يكون ذلك لأجل مخافة الناس. السعدي:٢٤٤.\nما الفرق بين خوف الله بالغيب وخوفه أمام الناس؟"],[124,"§المائدة\nwords\nوَلِلسَّيَّارَةِلِلمُسَافِرِينَ.\nوَالقَلاَئِدَهُوَ الهَديُ الَّذِي عُلِّقَ عَلَيهِ شَيءٌ؛ إِشعَارًا بِأَنَّهُ هَديٌ.\nبَحِيرَةٍالَّتِي تُقطَعُ أُذُنُهَا، وَتُخَلَّى لِلطَّوَاغِيتِ؛ إِذَا وَلَدَت عَدَدًا مِنَ البُطُونِ.\nسَائِبَةٍالَّتِي تُترَكُ لِلأَصنَامِ؛ بِسَبَبِ بُرءٍ مِن مَرَضٍ، أَو نَجَاةٍ مِن هَلاَكٍ.\ndeeds\nحدد منكرات وبلغ حكم الله فيها لتبرأ ذمتك.\nأرسل رسالة تبين فيها أن الله سبحانه يحب السؤال إذا كان بقصد العمل، ويكره السؤال المتعنت والمرائي.\nأرسل رسـالة تبين فيها خـطورة تحـريم الحـلال وتحليل الحرام.\nguid\nالقليل الحلال خيرٌ وأنفع من الكثير الحرام الضار.\nالمال الخبيث لا ينفع صاحبه شيئًا، بل يضره في دينه ودنياه.\nلا تُكثِر من سؤال العالم عن الأمور التي لا فائدة من وراءها.\nrefl\nٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ٩٨\nجعل الرحمة صفة له مذكورة في أسمائه الحسنى، وأمَّا العذاب والعقاب فجعلهما من مفعولاته، غير مذكورين في أسمائه. ابن تيمية:٢/٥٦١.\nالآية تورث في الإنسان الخوف والرجاء، بيّن ذلك.\nٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ٩٨\nأي: ليكن هذان العلمان موجودين في قلوبكم على وجه الجزم واليقين؛ تعلمون أنه شديد العقاب العاجل والآجل على من عصاه، وأنه غفور رحيم لمن تاب إليه وأطاعه؛ فيثمر لكم هذا العلم الخوف من عقابه، والرجاء لمغفرته وثوابه، وتعملون على ما يقتضيه الخوف والرجاء. السعدي:٢٤٥.\nما الفائدة من العلم بأن الله شديد العقاب، وأنه غفور رحيم؟\nمَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ٩٩\n﴿مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ﴾ أي: ليس له الهداية والتوفيق ولا الثواب، وإنَّما عليه البلاغ. القرطبي:٨/٢٢٥.\nحدد وظيفة الداعية إلى الله -عز وجل-.\nقُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ١٠٠\nفالخبيث لا يساوي الطيب مقدارًا، ولا إنفاقًا، ولا مكانًا، ولا ذهابًا؛ فالطيب يأخذ جهة اليمين، والخبيث يأخذ جهة الشمال، والطيب في الجنة، والخبيث في النار. القرطبي:٨/٢٢٦.\nبيّن لماذا لا يساوي الخبيث الطيب.\nقُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ١٠٠\nيقول: لا يعتدل العاصي والمطيع لله عند الله، ولو كثر أهل المعاصي فعجبت من كثرتهم؛ لأن أهل طاعة الله هم المفلحون الفائزون بثواب الله يوم القيامة وإن قلوا دون أهل معصيته، وإن أهل معاصيه هم الأخسرون الخائبون وإن كثروا... فلا تعجبن من كثرة من يعصي الله فيمهله، ولا يعاجله بالعقوبة؛ فإن العقبى الصالحة لأهل طاعة الله. الطبري:١١/٩٦.\nالعاقل لا يغتر بكثرة أهل الباطل، وضح ذلك في ضوء الآية.\nقُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ١٠٠\n﴿وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ﴾: فإنه لا ينفع صاحبه شيئًا، بل يضره في دينه ودنياه. (فاتقوا الله يا أولي الألباب لعلكم تفلحون): فأمر أولي الألباب؛ أي: أهل العقول الوافية، والآراء الكاملة؛ فإن الله تعالى يوجه إليهم الخطاب، وهم الذين يؤبه لهم، ويرجى أن يكون فيهم خير، ثم أخبر أن الفلاح متوقف على التقوى التي هي موافقة الله في أمره ونهيه؛ فمن اتقاه أفلح كل الفلاح، ومن ترك تقواه حصل له الخسران، وفاتته الأرباح. السعدي:٢٤٥.\nلماذا توجه الله سبحانه بالخطاب لأولي الألباب دون سائر الناس؟\nقَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ ١٠٢\nلأنهم لم يسألوا على وجه الاسترشاد، بل على وجه الاستهزاء والعناد. ابن كثير:٢/١٠٠.\nتختلف أحوال السائلين، فما السؤال المحمود، وما السؤال المذموم؟"],[125,"§المائدة\nwords\nحَسبُنَاكَافِينَا.\nعَلَيكُم أَنفُسَكُمأَلزِمُوا أَنفُسَكُمُ العَمَلَ بِالطَّاعَةِ.\nضَرَبتُم فِي الأَرضِسَافَرتُم.\nالأَولَيَانِالأَقرَبَانِ لِلمَيِّتِ.\ndeeds\nأنكر اليوم منكرًا بنصيحة مؤثرة، وكلمة طيبة، لعلك تكون ممن يرفع الله بهم العذاب عن أهل الأرض.\nاكتب وصيتك قبل نومك هذه الليلة.\nانصح من حولك بالحرص على كتابة الوصية.\nguid\nمن أهم أسباب ضياع الناس في دينهم ودنياهم: ترك اتباع ما أنزل الله، وتقليد الآباء والمجتمع في أخطائهم.\nاتباع العادات والتقاليد محمود إذا لم يخالف شرع الله.\nضلال الناس لا يضر المؤمنين إذا أمروهم بالمعروف، ونهوهم عن المنكر.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ\nولا يدل هذا على أن الأمر بالمعروف والنهي عن المنكر لا يضر العبد تركهما وإهمالهما، فإنه لا يتم هداه إلا بالإتيان بما يجب عليه من الأمر بالمعروف والنهي عن المنكر، نعم إذا كان عاجزًا عن إنكار المنكر بيده ولسانه، وأنكره بقلبه فإنه لا يضره ضلال غيره. السعدي:٢٤٦.\nكيف ترد على من يستدل بهذه الآية على ترك الأمر بالمعروف والنهي عن المنكر؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ\nقد يتوهم الجاهل من ظاهر هذه الآية الكريمة عدم وجوب الأمر بالمعروف والنهي عن المنكر، ولكن نفس الآية فيها الإشارة إلى أن ذلك فيما إذا بلغ جهده، فلم يقبل منه المأمور؛ وذلك في قوله: ﴿إِذَا ٱهۡتَدَيۡتُمۡۚ﴾ لأن من ترك الأمر بالمعروف لم يهتد. الشنقيطي:١/٤٥٩.\nمتى يقتصر ضرر الضلالة على صاحبها دون غيره؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ\nالوصية معتبرة، ولو كان الإنسان وصل إلى مقدمات الموت وعلاماته، ما دام عقله ثابتًا. السعدي:٢٤٧.\nهل يجوز لمن حضره الموت أن يوصي؟ وماذا تفيد من ذلك؟\nفَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ\nوسمى الله تعالى الموت في هذه الآية مصيبة، والموت، وإن كان مصيبة عظمى ورزية كبرى؛ فأعظم منه الغفلة عنه، والإعراض عن ذكره، وترك التفكر فيه، وترك العمل له، وإن فيه وحده لعبرة لمن اعتبر، وفكرة لمن تفكر. القرطبي:٨/٢٦٤.\nهل الموت مصيبة؟ وما المصيبة الأشد والأعظم منه؟\nتَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ\nإن فائدة اشتراطه بعد الصلاة: تعظيمًا للوقت، وإرهابًا به؛ لشهود الملائكة ذلك الوقت. القرطبي:٨/٢٦٦.\nلماذا اشترط أن يكون الحلف واليمين بعد الصلاة؟\nفَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ ١٠٦\n﴿وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ﴾ أي: الشهادة التي أمر الله بحفظها وأدائها. وإضافتها إلى الله تعظيمًا لها. ابن جزي:١/٢٥٥.\nما وجه إضافة الشهادة إلى الله -عز وجل-؟\nوَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ١٠٨\n﴿وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ﴾: سمع إجابة وقَبول جميع ما تُؤمرون به، ﴿وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ﴾: تذييل لما تقدم، والمراد: فإن لم تتقوا وتسمعوا كنتم فاسقين خارجين عن الطاعة، واللهُ تعالى لا يهدي القوم الخارجين عن طاعته؛ لا يهديهم إلى ما ينفعهم أو إلى طريق الجنة. الألوسي:٧/٦٩.\nفي الآية بيان لمانع من موانع الهداية والتوفيق، بيِّن ذلك المانع."],[126,"§المائدة\nwords\nأَيَّدتُّكَقَوَّيتُكَ.\nبِرُوحِ القُدُسِجِبرِيلَ -عليه السلام-.\nالأَكمَهَمَن وُلِدَ أَعمَى.\nالحَوَارِيُّونَأَصفِيَاءُ عِيسَى -عليه السلام-.\ndeeds\nاقرأ في أهوال يوم القيامة، وكيف يكون حال الناس في ذلك اليوم العظيم.\nاقرأ قصة عيسى -عليه السلام- من أحد كتب قصص الأنبياء، واستخرج منها فائدتين.\nتذكر ثلاثًا من نعم الله تعالى عليك، ثم اشكر الله عليها قولًا وعملًا.\nguid\nشدة هول يوم القيامة، وصعوبة الموقف على الرسل، فكيف بمن دونهم؟\nاعلم أن نعمة الله تعالى على أبويك أو أحدهما هي نعمة عليك أيضًا، فاشكر الله تعالى على ذلك.\nتذكُّر نعم الله تعالى على العبد يعين على القيام بواجب شكرها.\nrefl\nيَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ ١٠٩\nأي: ماذا أجابكم به الأمم من إيمان وكفر، وطاعة ومعصية؟ والمقصود بهذا السؤال توبيخ من كفر من الأمم، وإقامة الحجة عليهم. ابن جزي:١/٢٥٦.\nما المراد بسؤال الله لأنبيائه مع علمه -جل وعلا- بذلك؟\nيَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ ١٠٩\n﴿قَالُواْ لَا عِلۡمَ لَنَآۖ﴾: إنَّما قالوا ذلك تأدبًا مع الله، فوكلوا العلم إليه. ابن جزي:١/٢٥٦.\nما وجه إجابة الأنبياء ربهم بهذا الجواب؟\nيَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ ١٠٩\nمعنى قولهم: ﴿لَا عِلۡمَ لَنَآ﴾: لم يكن ذلك من الرسل إنكارًا أن يكونوا كانوا عالمين بما عملت أممهم، ولكنهم ذهلوا عن الجواب من هول ذلك اليوم، ثم أجابوا بعد أن ثابت إليهم عقولهم بالشهادة على أممهم. الطبري:١١/٢١٠.\nأجاب الرسل بجوابين؛ فما هما؟ ومتى يكونان؟\nإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيَۡٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ\nوهذا كله صريح في أنه ليس هو الله، وإنَّما هو عبد الله؛ فعل ذلك بإذن الله، كما فعل مثل ذلك غيره من الأنبياء، وصريح بأن الآذن غير المأذون له. ابن تيمية:٢/٥٧١.\nالآية الكريمة دليل أن عيسى -عليه السلام- عبد لله، لا كما تقول النصارى، كيف ذلك؟\nٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ\nاذكرها بقلبك، ولسانك، وقم بواجبها؛ شكرًا لربك؛ حيث أنعم عليك نعمًا ما أنعم بها على غيرك. السعدي:٢٤٨.\nهل اختصك الله بنعمة؟ وما الواجب عليك تجاهها؟\nوَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ\n(بإذني): كرره مع كل معجزة ردًّا على من نسب الربوبية إلى عيسى. ابن جزي:١/٢٥٧.\nلمَ تكررت كلمة (بإذني) في كل معجزة؟\nقَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّٰهِدِينَ ١١٣\nأي: إنَّما سألنا لأنا نريد أن نأكل منها؛ أكل تبرك لا أكل حاجة، فنستيقن قدرته، وتطمئن وتسكن قلوبنا، ونعلم أن قد صدقتنا بأنك رسول الله؛ أي: نزداد إيمانًا ويقينًا. البغوي:١/٧٣٢.\nلماذا طلب الحواريون من عيسى -عليه السلام- إنزال المائدة؟"],[127,"§المائدة\nwords\nتَكُونُ لَنَا عِيدًانَتَّخِذُ يَومَ نُزُولِهَا عِيدًا نُعَظِّمُهُ نَحنُ، وَمَن بَعدَنا.\nوَآيَةً مِنكَعَلاَمَةً عَلَى وَحدَانِيَّتِكَ وَنُبُوَّتِي.\nشَهِيدًاشَاهِدًا.\ndeeds\nكرر هذا الدعاء في هذا اليوم: \"اللهم ارزقني وأنت خير الرازقين\"؛ كما دعا به الأنبياء من قبل.\nكرر هذه الآية في هذه الليلة، وتدبر في معانيها، كما فعل النبي -صلى الله عليه وسلم-.\nسل الله تعالى أن يرزقك الصدق في القول والعمل.\nguid\nإياك أن تعاهد الله تعالى، ثم يعطيك ما تريد، فتنقض عهدك؛ فإن ذلك مظنة العذاب الشديد.\nمن علامة إيمان العبد تأدبه في خطابه مع ربه -سبحانه وتعالى-.\nفضيلة الصدق؛ فهو نافع في الدنيا والآخرة.\nrefl\nقَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ١١٥\nقال عبد الله بن عمر: \"أشدّ الناس عذابًا يوم القيامة من كفر من أصحاب المائدة، وآل فرعون، والمنافقون\". ابن جزي:١/٢٥٨.\nالمعصية بعد وضوح الحجة أشد من المعصية ابتداءً، وضح ذلك.\nوَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ ١١٦\n﴿إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ﴾: اعتذار، وبراءة من ذلك القول، ووكل العلم إلى الله لتظهر براءته؛ لأن الله علم أنه لم يقل ذلك. ابن جزي:١/٢٥٩.\nبيّن أدب عيسى مع ربه -سبحانه وتعالى- في هذه الآية في ثلاث نقاط.\nوَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ\nوبدأ بالتسبيح قبل الجواب لأمرين؛ أحدهما: تنزيهًا له عما أضيف إليه، الثاني: خضوعًا لعزته، وخوفًا من سطوته. القرطبي:٨/٣٠٢.\nلماذا ابتدأ بتسبيح الله تعالى؟ وأي شيء نتعلمه من ذلك؟\nإِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ\nخص النفس بالذكر لأنها مظنة الكتم، والانطواء على المعلومات. ابن عطية:٢/٢٦٣.\nما وجه تخصيص النفس بالذكر؟\nإِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ١١٨\nلم يقل: \"الغفور الرحيم\"؛ وهذا من أبلغ الأدب مع الله تعالى؛ فإنه قال في وقت غضب الرب عليهم، والأمر بهم إلى النار؛ فليس هو مقام استعطاف ولا شفاعة، بل مقام براءة منهم... والمعنى: إن غفرت لهم فمغفرتك تكون عن كمال القدرة والعلم، ليست عن عجز الانتقام منهم، ولا عن خفاء عليك بمقدار جرائمهم. ابن القيم:١/٣٣٧.\nلم قال في الآية الكريمة: ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾، ولم يقل: \"الغفور الرحيم\"؟\nقَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١١٩\n﴿قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ﴾: عموم في جميع الصادقين، وخصوصًا في عيسى ابن مريم؛ فإن في ذلك إشارة إلى صدقه في الكلام الذي حكاه الله عنه. ابن جزي:١/٢٦٠.\nبيّن وجه هذه الآية في فضيلة الصدق.\nقَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ\nفدخل تحت هذه العبارة كل مؤمن بالله تعالى، وكل ما كان أتقى فهو أدخل في العبارة، ثم جاءت هذه العبارة مشيرة إلى عيسى في حاله تلك وصدقه فيما قال؛ فحصل له بذلك في الموقف شرف عظيم؛ وإن كان اللفظ يعمه وسواه. ابن عطية:٢/٢٦٣.\nفي الصدق منجاة في الدنيا والآخرة، وضح ذلك من خلال الآية."],[128,"§الأنعام\nwords\nوَجَعَلَخَلَقَ.\nيَعدِلُونَيُسَوُّونَ بِهِ غَيرَهُ، وَيُشرِكُونَ.\nتَمتَرُونَتَشُكُّونَ.\nوَهُوَ اللَّهُالإِلَهُ المَعبُودُ بِحَقٍّ.\nقَرنٍأُمَّةٍ مِنَ النَّاسِ.\nمِدرَارًاغَزِيرًا.\nلاَ يُنظَرُونَلاَ يُمهَلُونَ.\ndeeds\nاعمل هذا اليوم لله تعالى طاعة في السر.\nحدد ثلاثة من أسباب إهلاك الأمم السابقة.\nحاول أن تربط بين مصيبة أصابتك ومعصية عصيت الله بها.\nguid\nأكثر من حمد الله -سبحانه وتعالى-؛ فإن حمد الله وشكره من أعظم العبادات التي تقربك إليه.\nالاستهزاء والسخرية بالدين من موجبات العذاب، وقرب وقوعه.\nما وقعت مصيبة إلا بذنب ولا رفعت إلا بتوبة.\nrefl\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ١\nقال العلماء: هذه السورة أصل في محاجة المشركين وغيرهم من المبتدعين، ومن كذب بالبعث والنشور، وهذا يقتضي إنزالها جملة واحدة؛ لأنها في معنى واحد من الحجة. القرطبي:٨/٣١٢.\nلماذا نزلت سورة الأنعام جملة واحدة؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ١\nيقول: أخلصوا الحمد والشكر للذي خلقكم أيها الناس، وخلق السماوات والأرض، ولا تشركوا معه في ذلك أحدًا أو شيئًا؛ فإنه المستوجب عليكم الحمد بأياديه عندكم ونعمه عليكم، لا من تعبدونه من دونه، وتجعلونه له شريكًا من خلقه. الطبري:١١/٢٤٧.\nلماذا يجب علينا إخلاص الحمد لله تعالى؟\nوَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ\nوذكر الله الظلمات بالجمع لكثرة موادها وتنوع طرقها، ووَحَّد النور لكون الصراط الموصلة إلى الله واحدة لا تعدد فيها؛ وهي الصراط المتضمنة للعلم بالحق والعمل به. السعدي:٢٥٠.\nما وجه جمع الظلمات وإفراد النور؟\nهُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ ٢\nووصفه ب ﴿مُّسَمًّى عِندَهُۥۖ﴾؛ لأنه استأثر بعلم وقت القيامة. ابن عطية:٢/٢٦٧.\nلماذا وصف الأجل بأنه ﴿مُّسَمًّى عِندَهُۥۖ﴾؟\nوَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ٤\nوالإعراض: ترك النظر في الآيات التي يجب أن يستدلوا بها على توحيد الله -جل وعز-؛ من خلق السموات والأرض وما بينهما. البغوي:٢/١٠٠.\nكيف يكون الإعراض عن آيات الله تعالى؟\nأَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ٦\nفاحذروا أيها المخاطبون أن يصيبكم مثل ما أصابهم؛ فما أنتم بأعز على الله منهم، والرسول الذي كذبتموه أكرم على الله من رسولهم؛ فأنتم أولى بالعذاب، ومعاجلة العقوبة منهم؛ لولا لطفه وإحسانه. ابن كثير:٢/١١٧.\nما سنة الله سبحانه في البلاد التي يكثر شرها على خيرها؟\nفَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ٦\nوالمعنى: وسعنا عليهم النعم فكفروها، ﴿فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ﴾ أي: بكفرهم؛ فالذنوب سبب الانتقام، وزوال النعم، ﴿وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ﴾ أي: أوجدنا. فليحذر هؤلاء من الإهلاك أيضًا. القرطبي:٨/٣٢٦.\nما سبب نزول عذاب الله تعالى؟"],[129,"§الأنعام\nwords\nوَلَلَبَسنَالَخَلَّطنَا حَتَّى يَشتَبِهَ عَلَيهِمُ الأَمرُ.\nفَحَاقَأَحَاطَ وَنَزَلَ.\nيَمسَسكَيُصِبكَ.\ndeeds\nأرسل رسالة تبيّن فيها خطر الاستهزاء بالخلق؛ وخاصة أهل الصلاح منهم.\nتذكر أن الله كتب على نفسه الرحمة، ثم اسأله وتضرع إليه أن يرحمك، وأن يجعلك رحيمًا بالخلق.\nإذا دعتك نفسك اليوم للوقوع في معصية فردد قول الله تعالى: \"إني أخاف إن عصيت ربي عذاب يوم عظيم\".\nguid\nلا تتخذ وليًا تصرف له عبادتك وتتكل عليه غير الله تعالى.\nإذا استهزأ بك أحد من الناس فتذكر أن المرسلين من قبلك استُهزئ بهم؛ فلا تحزن؛ فإن العاقبة للتقوى.\nبادر بالانقياد للأوامر الربانية.\nrefl\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ١١\nفإن شككتم في ذلك، أو ارتبتم؛ فسيروا في الأرض، ثم انظروا كيف كان عاقبة المكذبين؛ فلن تجدوا إلا قومًا مهلكين... وهذا السير المأمور به: سير القلوب والأبدان الذي يتولد منه الاعتبار، وأمَّا مجرد النظر من غير اعتبار فإن ذلك لا يفيد شيئًا. السعدي:٢٥١.\nما الفرق بين المسلم وغيره حينما يرى آثار القوم المهلكين؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ١٢\nهذا استعطاف منه تعالى للمتولين عنه إلى الإقبال عليه، وإخبار بأنه رحيم بالعباد لا يعجل بالعقوبة، ويقبل الإنابة والتوبة. البغوي:٢/١٠.\nما المقصود الذي أراده الله تعالى بالآية ؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ\nوهو تعالى قد بسط عليهم رحمته وإحسانه، وتغمدهم برحمته وامتنانه، وكتب على نفسه كتابًا أن رحمته تغلب غضبه، وأن العطاء أحب إليه من المنع، وأن الله قد فتح لجميع العباد أبواب الرحمة إن لم يغلقوا عليهم أبوابها بذنوبهم، ودعاهم إليها إن لم تمنعهم من طلبها معاصيهم وعيوبهم. السعدي:٢٥١.\nما الذي يمنع العبد من الإفادة من رحمة ربه -سبحانه وتعالى-؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ\nالإخبار بأن لله ما في السماوات وما في الأرض يثير سؤال سائل عن عدم تعجيل أخذهم على شركهم بمن هم ملكه؛ فالكافر يقول: لو كان ما تقولون صدقًا لعجل لنا العذاب، والمؤمن يستبطئ تأخير عقابهم، فكان قوله: ﴿كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ﴾ جوابًا لكلا الفريقين بأنه تفضل بالرحمة؛ فمنها: رحمة كاملة؛ وهذه رحمته بعباده الصالحين، ومنها: رحمة موقتة؛ وهي رحمة الإمهال والإملاء للعصاة والضالين. ابن عاشور:٧/١٥١.\nما مناسبة ﴿كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ﴾ لما قبلها؟\nوَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١٣\nخص السكون بالذكر؛ لأن النعمة فيه أكثر. البغوي:٢/١١.\nلماذا خص تعالى السكون بالذكر؟\nقُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ١٤\nويجوز أن يكون الأول كناية عن الأقوى والأمكن في الإسلام؛ لأن الأول في كل عمل هو الأحرص عليه، والأعلق به؛ فالأولية تستلزم الحرص والقوة في العمل، كما حكى الله تعالى عن موسى قوله: ﴿وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ﴾ [الأعراف: ١٤٣]، فإن كونه أولهم معلوم، وإنَّما أراد: أني الآن بعد الصعقة أقوى الناس إيمانًا. ابن عاشور:٧/ ١٥٨.\nما المقصود بالأولية هنا؟ وماذا تفيد من ذلك؟\nوَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ١٧\nأشار تعالى بقوله هنا: ﴿فَهُوَ عَلَىٰ كُلِّ شَيۡءٍ قَدِيرٌ﴾ بعد قوله: ﴿وَإِن يَمۡسَسۡكَ بِخَيۡرٍ﴾ إلى أن فضله وعطاءه الجزيل لا يقدر أحد على رده عمن أراده له تعالى؛ كما صرح بذلك في قوله: ﴿وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦ﴾ [يونس: ١٠٧] الآية. الشنقيطي:١/٤٧٥.\nما مناسبة ختم هذه الآية بـ ﴿فَهُوَ عَلَىٰ كُلِّ شَيۡءٍ قَدِيرٌ﴾ ؟"],[130,"§الأنعام\nwords\nفِتنَتُهُمإِجَابَتُهُم.\nأَكِنَّةًأَغطِيَةً.\nوَقرًاثِقَلًا وَصَمَمًا.\nأَسَاطِيرُ الأَوَّلِينَحِكَايَاتُهُمُ الَّتِي لاَ حَقِيقَةَ لَهَا.\nوَيَنأَونَيَبتَعِدُونَ.\ndeeds\nكرر اليوم هذا الدعاء: \"رب زدني علمًا\".\nتذكر مسألة شرعية لم تفهمها، ثم أكثر من الاستغفار؛ لعلك توفق لفهمها.\nزُر المقبرة، أو تأمل صورة لقبر، ثم تذكر هذه الآية.\nguid\nالكذب على النفس، وإقناعها بالمعاصي، والتهاون في الطاعات، لا ينفعك يوم القيامة؛ لأنه وقت تكشف الحقائق.\nالآراء والمعتقدات الباطلة ستضل عن صاحبها يوم القيامة.\nالذنوب توجد حائلًا بين العبد وتدبر كتاب الله.\nrefl\nقُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ\nوهو يشهد لي بإقراره وفعله، فيُقِرُّني على ما قلت لكم... فالله حكيم قدير، فلا يليق بحكمته وقدرته أن يُقِرَّ كاذبًا عليه، زاعمًا أن الله أرسله ولم يرسله، وأن الله أمره بدعوة الخلق ولم يأمره، وأن الله أباح له دماء من خالفه وأموالهم ونساءهم، وهو مع ذلك يصدقه بإقراره وبفعله، فيؤيده على ما قال بالمعجزات الباهرة والآيات الظاهرة، وينصره ويخذل من خالفه وعاداه، فأي شهادة أكبر من هذه الشهادة؟! السعدي:٢٥٢-٢٥٣.\nما وجه كون الله شهيدًا بين الرسول ومن كذبه؟\nوَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ\nأمر بتبليغ الأقرب منه مكانًا ونسبًا، ثم بتبليغ طائفة بعد طائفة حتى تبلغ النذارة إلى جميع أهل الأرض؛ كما قال تعالى: ﴿وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ﴾ أي: من بلغه القرآن؛ فكل من بلغه القرآن فقد أنذره محمد -صلى الله عليه وسلم-. ابن تيمية:٣/٢٠.\nتبليغ هذا الدين واجب شرعي، فكيف تكون خطواته؟\nوَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ\n﴿وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ﴾ عقابَه، وأُنذِرَ به من بلغه من سائر الناس غيركم؛ إن لم ينته إلى العمل بما فيه، وتحليل حلاله وتحريم حرامه، والإيمان بجميعه، نزول نقمة الله به. الطبري:١١/٢٩٠.\nالمقصد الأكبر من إنزال القرآن هو العمل به، وضح ذلك.\nٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ٢٤\n﴿وَضَلَّ عَنۡهُم﴾: زال وذهب عنهم ﴿مَّا كَانُواْ يَفۡتَرُونَ﴾ من الأصنام؛ وذلك أنهم كانوا يرجون شفاعتها ونصرتها؛ فبطل كله في ذلك اليوم. البغوي:٢/١٤.\nكيف ضل عنهم باطلهم في ذلك اليوم؟\nوَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ\nأي: ومن هؤلاء المشركين قوم يحملهم بعض الأوقات بعض الدواعي إلى الاستماع لما تقول، ولكنه استماع خال من قصد الحق واتباعه؛ ولهذا لا ينتفعون بذلك الاستماع، لعدم إرادتهم للخير، ﴿وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً﴾ أي: أغطية وأغشية؛ لئلَّا يفقهوا كلام الله، فصان كلامه عن أمثال هؤلاء. السعدي:٢٥٤.\nهل الابتعاد عن القرآن عقوبةٌ ربانية؟ وضح ذلك من خلال الآية.\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ\n﴿وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ﴾: (أكنة) جمع كنان؛ وهو الغطاء، و﴿أَن يَفۡقَهُوهُ﴾ في موضع مفعول من أجله؛ تقديره: كراهة أن يفقهوه، ومعنى الآية: أن الله حال بينهم وبين فهم القرآن إذا استمعوه، وعبر بالأكنة والوقر مبالغة. ابن جزي: ١ / ٢٦٦.\nبيّن سبب عدم انتفاع الكفار بالقرآن.\nوَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ٢٦\nأي: لا يرجع وبال فعلهم إلا إليهم، وأوزار الذين يصدونهم عليهم ﴿وَمَا يَشۡعُرُونَ﴾. البغوي: ٢/١٦.\nقد يحمل الإنسان إثمه وإثم غيره، كيف يكون ذلك؟"],[131,"§الأنعام\nwords\nكَبُرَعَظُمَ.\ndeeds\nأكثر اليوم من الأعمال الصالحة، وزد في صلاتك النافلة؛ حتى لا تتحسر يوم القيامة على التفريط.\nحدد عبادة تتمنى فعلها، ولكن أخرتها بالتسويف، ثم بادر بفعلها اليوم.\nادعُ أحد أقاربك أو معارفك للخير، واصبر على أذاهم.\nguid\nالذنوب أسوأ حمل يحمله الإنسان يوم القيامة.\nنصيحة القرآن للعقلاء بأن لا يغتروا بالحياة الدنيا ويهملوا شأن الآخرة؛ فهي خير للعبد.\nعلى الداعية أن لا يستغرب تكذيب الناس له؛ فإن الناس قد كذبت المرسلين من قبله.\nrefl\nبَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ٢٨\nبل ظهر لهم ما كانوا يجحدونه من الشرك، فيقولون: ﴿وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ﴾ [الأنعام: ٢٣]، فينطق الله جوارحهم، فتشهد عليهم بالكفر. القرطبي: ٨/٣٥٤.\nما الذي كانوا يخفونه من قبل؟ وكيف بدا لهم؟\nوَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ٣٢\nأما حقيقة الدنيا: فإنها لعب ولهو؛ لعب في الأبدان، ولهو في القلوب؛ فالقلوب لها والهة، والنفوس لها عاشقة، والهموم فيها متعلقة، والاشتغال بها كلعب الصبيان وأمَّا الآخرة، فإنها ﴿خَيۡرٌ لِّلَّذِينَ يَتَّقُونَۚ﴾ في ذاتها وصفاتها، وبقائها ودوامها، وفيها ما تشتهيه الأنفس، وتلذ الأعين، من نعيم القلوب والأرواح، وكثرة السرور والأفراح، ولكنها ليست لكل أحد، وإنَّما هي للمتقين الذين يفعلون أوامر الله، ويتركون نواهيه وزواجره. السعدي:٢٥٢-٢٥٣.\nاذكر فرقين بين متاع الدنيا ونعيم الآخرة؟\nوَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ٣٢\nليس من اللهو واللعب ما كان من أمور الآخرة؛ فإن حقيقة اللعب: ما لا ينتفع به، واللهو: ما يُلهى به. وما كان مرادًا للآخرة خارج عنهما... قال ابن عباس: \"هذه حياة الكافر؛ لأنه يزجيها في غرور وباطل، فأما حياة المؤمن فتنطوي على أعمال صالحة، فلا تكون لهوًا ولعبًا\". القرطبي: ٨/٣٦١.\nهل كل ما في الدنيا لهو ولعب؟\nفَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ٣٣\nنفى عنهم التكذيب، وأثبت الجحود، ومعلوم أن التكذيب باللسان لم يكن منتفيًّا عنهم، فعلم أنه نفى عنهم تكذيب القلب. ابن تيمية:٣/٢٣.\nما التكذيب المنفي في الآية الكريمة؟\nوَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ\nفاصبر كما صبروا تظفر كما ظفروا. السعدي:٢٥٥.\nما الحكمة من وراء الإخبار عن قصص المرسلين وسيرهم؟\nوَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ ٣٤\n(وَلَقَد جاءَكَ مِن نَبَإِ المُرسَلِينَ) أي: من أخبارهم؛ ويعني بذلك صبرهم ثم نصرهم، وهذا أيضًا تقوية للوعد والحض على الصبر. ابن جزي:١/٢٦٦.\nالمقصد الأكبر من إنزال القرآن هو العمل به، وضح ذلك.\nوَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ ٣٥\nأمر الله نبيه ألا يشتد حزنه عليهم إذا كانوا لا يؤمنون، كما أنه لا يستطيع هداهم. القرطبي ٨/٣٦٧.\nما الحكمة من نهي الداعية عن الحزن من إعراض المدعوين؟"],[132,"§الأنعام\nwords\nمَا فَرَّطنَامَا تَرَكنَا.\nصُمٌّالَّذِينَ لاَ يَسمَعُونَ.\nوَبُكمٌالَّذِينَ لاَ يَتَكَلَّمُونَ.\nأَرَأَيتَكُمأَخبِرُونِي.\nمُبلِسُونَآيِسُونَ، مُنقَطِعُونَ مِن كُلِّ خَيرٍ.\ndeeds\nحدد نوعًا من البهائم أو الطيور، وتفكر فيها، وكيف أنها أمة من الأمم.\nتأمل ما سمعته من الآيات في الصلاة هذا اليوم، وكم فيها من أوامر ونواهٍ، وكم طبقت منها.\nحدد كربًا أصابك، ثم ألح على الله بالدعاء بتفريجه.\nguid\nالهداية بيد الله؛ فاطلبها ممن هي بيده.\nالمرض أو الفقر وآفات الدنيا قد تذكرك بالله -سبحانه وتعالى- وترجعك إليه.\nانفتاح الدنيا إذا كان مصاحبًا للبعد عن شرع الله فقد يكون سببًا أو مقدمة للهلاك.\nrefl\nإِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ\nالمراد بالسماع هنا: سماع القلب والاستجابة، وإلا فمجرد سماع الأذن يشترك فيه البر والفاجر؛ فكل المكلفين قد قامت عليهم حجة الله تعالى باستماع آياته. السعدي:٢٥٥.\nما الفرق في سماع المواعظ بين المؤمن والغافل؟\nوَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ\nيعني بذلك الكفار؛ لأنهم موتى القلوب، فشبههم الله بأموات الأجساد. ابن كثير:٢/١٢٤.\nما وجه الشبه بين الكافر والميت؟\nمَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ ٣٨\nجميع الأشياء -صغيرها وكبيرها- مثبتة في اللوح المحفوظ على ما هي عليه، فتقع جميع الحوادث طبق ما جرى به القلم، وفي هذه الآية دليل على أن الكتاب الأول قد حوى جميع الكائنات، وهذا أحد مراتب القضاء والقدر؛ فإنها أربع مراتب: علم الله الشامل لجميع الأشياء، وكتابه المحيط بجميع الموجودات، ومشيئته وقدرته النافذة العامة لكل شيء، وخلقه لجميع المخلوقات. السعدي:٢٥٥.\nكل ما يقع في حياتك يمر بأربع مراتب مقدرة، فما هي؟\nوَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ٤٢ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ٤٣\nذم الله سبحانه حزبين: ...حزب إذا نزل بهم الضرّ لم يدعوا الله ولم يتضرعوا إليه ولم يتوبوا إليه؛ كما قال: ﴿وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٍ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ﴾... وحزب يتضرعون إليه في حال الضراء ويتوبون إليه، فإذا كشفها عنهم أعرضوا عنه... والممدوح هو القسم الثالث: وهم الذين يدعونه ويتوبون إليه، ويثبتون على عبادته والتوبة إليه في حال السراء؛ فيعبدونه ويطيعونه في السراء والضراء. ابن تيمية:٣/٢٤-٢٥.\nاذكر أقسام الناس في الدعاء حال السراء والضراء.\nوَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ٤٢ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ٤٣\n﴿فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ﴾: كان ذلك على وجه التخفيف والتأديب، (فلولا): هذا عرض وتحضيض. وفيه دليل على نفع التضرع حين الشدائد. ابن جزي:١/٢٧٠.\nفي ضوء الآية بين أهمية التضرع في الشدائد.\nفَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ٤٤\nفتحنا عليهم أبواب كل شيء كان مغلقًا عنهم، ﴿حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ﴾ معناه: بطروا، وأشروا، وأعجبوا، وظنوا أن ذلك العطاء لا يبيد، وأنه دالٌّ على رضاء الله -عز وجل- عنهم، ﴿أَخَذۡنَٰهُم بَغۡتَةً﴾ أي: استأصلناهم، وسطونا بهم، و(بغتة) معناه: فجأة؛ وهي الأخذ على غرّة. القرطبي:٨/٣٧٩.\nبيّن استدراج الله سبحانه للغافلين من خلال الآية.\nفَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ٤٤\nقال الحسن البصري: \"من وَسَّعَ الله عليه فلم يرَ أنه يَمكُرُ به؛ فلا رأي له، ومن قَتَّرَ عليه فلم يرَ أنه يَنظُرُ له؛ فلا رَأيَ له\"، ثم قرأ هذه الآية. ابن كثير:٢/١٢٦.\nكيف يتعامل المسلم مع أحواله المالية من سَعَةٍ وضيق؟"],[133,"§الأنعام\nwords\nفَقُطِعَاُستُؤصِلَ.\nدَابِرُالقَومِ آخِرُهُم.\nنُصَرِّفُنُنَوِّعُ.\nيَصدِفُونَيُعرِضُونَ.\nبِالغَدَاةِأَوَّلِ النَّهَارِ.\ndeeds\nبين لمن حولك حقيقة الكهان والعرافين والمنجمين؛ فهم لا يعلمون الغيب.\nأرسل رسالة لمن حولك فيها موعظة قرآنية.\nاجلس اليوم مع بعض الفقراء أو الضعفاء الصالحين؛ ففيها تربية لقلبك على التواضع ولين الجانب.\nguid\nهلاك الظالمين لا مناص منه عاجلًا أو آجلًا.\nاستخدم البشارة بالخير، والتخويف من الشر في نصيحتك ودعوتك إلى الله تعالى.\nإذا كان رسول الله وحبيبه لا يعلم الغيب، فمن باب أولى أن يكون غيره لا يعلم الغيب.\nrefl\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nوالحمد لله رب العالمين على ما قضاه وقدره من هلاك المكذبين؛ فإن بذلك تتبين آياته، وإكرامه لأوليائه، وإهانته لأعدائه، وصدق ما جاءت به المرسلون. السعدي:٢٥٦.\nما وجه ختم آيات عذاب المشركين بالحمد؟\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nوفي ذلك كله تنبيه على أنه يحق الحمد لله عند هلاك الظلمة؛ لأن هلاكهم صلاح للناس، والصلاح أعظم النعم، وشكر النعمة واجب، وهذا الحمد شكر؛ لأنه مقابل نعمة. ابن عاشور:٧/٢٣٢.\nهلاك الظلمة نعمة من الله تعالى، بيّن ذلك.\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nحمد الله نفسه على أن قطع دابرهم؛ لأنه نعمة على الرسل، فذكر الحمد لله تعليمًا لهم ولمن آمن بهم أن يحمدوا الله على كفايته شر الظالمين. البغوي:٢/٢٢.\nما المشروع لنا إذا رأينا إهلاك الله تعالى للظالمين؟\nقُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ ٤٦\nوتصريف الآيات: اختلاف أنواعها؛ بأن تأتي مرة بحجج من مشاهدات في السماوات والأرض، وأخرى بحجج من دلائل في نفوس الناس، ومرة بحجج من أحوال الأمم الخالية التي أنشأها الله. ابن عاشور:٧/٢٣٥.\nكيف يكون تصريف الآيات المذكور في الآية الكريمة؟\nوَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ\nهذا القرآن نذارة للخلق كلهم، ولكن إنَّما ينتفع به ﴿ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ﴾ فهم متيقنون للانتقال من هذه الدار إلى دار القرار؛ فلذلك يستصحبون ما ينفعهم، ويدعون ما يضرهم. السعدي:٢٥٧.\nلماذا خُصِّصت النذارة بالخائفين من الحشر؟\nوَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ\nوخص الغداة والعشي بالذكر؛ لأن الشغل غالب فيهما على الناس، ومن كان في وقت الشغل مقبلًا على العبادة كان في وقت الفراغ من الشغل أعمل. القرطبي:٨/٣٨٩.\nلماذا خص الله سبحانه وقت الغداة والعشي بالذكر؟\nوَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ ٥٢\nنزلت في ضعفاء المؤمنين؛ كبلال، وعمار بن ياسر، وعبد الله بن مسعود، وخباب، وصهيب، وأمثالهم، وكان بعض المشركين من قريش قد قالوا للنبي -صلّى الله عليه وآله وسلّم-: لا يمكننا أن نختلط مع هؤلاء لشرفنا، فلو طردتهم لاتبعناك. ابن جزي:١/٢٧١.\nرسمت هذه الآية منهجية دعوية في التعامل مع المدعوين، بيِّنها."],[134,"§الأنعام\nwords\nفَتَنَّاابتَلَينَا بِاختِلاَفِ الأَرزَاقِ وَغَيرِهَا.\nبِجَهَالَةٍبِسَفَاهَةٍ، وَكُلُّ عَاصٍ للهِ فَهُوَ جَاهِلٌ.\nمَفَاتِحُ الغَيبِخَزَائِنُ الغَيبِ؛ وَهِيَ خَمسٌ مَذكُورَةٌ فِي آخِرِ لُقمَانَ.\ndeeds\nاشكر الله تعالى على نعمه عليك؛ فالشكر مفتاح للهداية والرزق.\nادعُ أحد الناس، واختر عبارات الترغيب برحمة الله تعالى.\nتذكر ذنبًا فعلته بجهل واستغفر الله منه.\nguid\nإذا علمت أن الله تعالى كتب على نفسه الرحمة فاسأله إياها بالدعاء والتضرع إليه.\nالقرآن هو الحاكم على مناهج الناس ومذاهبهم، فيبين الصحيح منها والفاسد.\nصبر الداعي وتحمله ما يلقاه من أهل الزيغ والضلال عبادة يتقرب بها إلى الله تعالى.\nrefl\nوَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ ٥٣\n﴿وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٍ﴾ أي: ابتلينا الكفار بالمؤمنين؛ وذلك أن الكفار كانوا يقولون: أهؤلاء العبيد والفقراء منّ الله عليهم بالتوفيق للحق والسعادة دوننا، ونحن أشراف أغنياء. وكان هذا الكلام منهم على وجه الاستبعاد بذلك. ﴿أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ﴾: ردّ على الكفار في قولهم المتقدّم. ابن جزي:١/٢٧١.\nكيف كانت هداية الضعفاء فتنةً واختبارًا للضالين؟\nأَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ ٥٣\nهم الذين يعرفون قدر نعمة الإيمان، ويشكرون الله عليها. ابن تيمية:٣/٢٨.\nما المقصود بالشاكرين في الآية الكريمة؟\nوَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ ٥٤\nوإذا جاءك المؤمنون فحَيِّهم، ورَحِّب بهم، ولقِّهِم منك تحيةً وسلامًا، وبشرهم بما ينشط عزائمهم وهممهم من رحمة الله، وسعة جوده، وإحسانه، وحُثَّهم على كل سبب وطريق يوصل لذلك، ورَهِّبهم من الإقامة على الذنوب، وأمُرهم بالتوبة من المعاصي لينالوا مغفرة ربهم وجوده. السعدي:٢٥٨.\nكيف تكون علاقة العلماء والدعاة بأتباعهم الصالحين؟\nوَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ٥٥\nوإذا بان سبيل المجرمين فقد بان سبيل المؤمنين. القرطبي:٨/٣٩٦.\nلم ذكر سبيل المجرمين، ولم يذكر سبيل المؤمنين؟\nوَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ٥٥\nفإن سبيل المجرمين إذا استبانت واتضحت أمكن اجتنابها والبعد منها، بخلاف ما لو كانت مشتبهة ملتبسة؛ فإنه لا يحصل هذا المقصود الجليل. السعدي:٢٥٨.\nما الحكمة من توضيح طرق المجرمين؟\nقُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ\nفأوقعته بكم، ولا خير لكم في ذلك، ولكن الأمر عند الحليم الصبور، الذي يعصيه العاصون، ويتجرأ عليه المتجرؤون، وهو يعافيهم ويرزقهم، ويسدي عليهم نعمه الظاهرة والباطنة. السعدي:٢٥٩.\nكيف تدل هذه الآية على سعة رحمة الله -سبحانه وتعالى-؟\nوَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا\n﴿وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا﴾ أي: من ورقة الشجر إلا يعلم متى تسقط، وأين تسقط، وكم تدور في الهواء، ولا حبة إلا يعلم متى تنبت، وكم تنبت، ومن يأكلها. القرطبي:٨/٤٠٥.\nذكرت الآية مثالًا يدل على سعة علم الله تعالى، وضحه."],[135,"§الأنعام\nwords\nجَرَحتُماكتَسَبتُم.\nلاَ يُفَرِّطُونَلاَ يُضَيِّعُونَ، وَلاَ يُقَصِّرُونَ.\nيَلبِسَكُم شِيَعًايَخلِطَكُم فِرَقًا مُتَنَاحِرَةً.\nنُصَرِّفُنُنَوِّعُ.\nيَخُوضُونَيَتَكَلَّمُونَ مُستَهزِئِينَ.\ndeeds\nتضرع إلى الله تعالى، وسله أن يفرج كربتك، ويقضي حاجتك؛ فإنه لا منجي من الشدائد إلا الله -سبحانه وتعالى-.\nاسع في الصلح بين شخصين أو فئتين متنازعتين.\nأرسل رسالة تحذر فيها من الوسائل الإعلامية التي تطعن في الدين.\nguid\nالتحذير من الاختلاف المفضي إلى الانقسام والنزاع.\nابتعد عن مجالس اللغو والباطل.\nهناك ملائكةٌ تحصي عليك أعمالك وأقوالك؛ فاحسب لكل عملٍ وقولٍ حسابه.\nrefl\nوَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ ٦٢\nلكمال علمه، وحفظه لأعمالهم، بما أثبته في اللوح المحفوظ، ثم أثبتته ملائكته في الكتاب الذي بأيديهم. السعدي:٢٥٩.\nتحدث عن عظمة الله -سبحانه وتعالى- في سرعة حسابه لعباده.\nقُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٦٣\n﴿لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ﴾: والشكر هو معرفة النعمة مع القيام بحقها. البغوي:٢/٣٠.\nكيف يكون الشكر الكامل لنعم الله تعالى؟\nقُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٦٣ قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ ٦٤\nفوبخهم الله في دعائهم إياه عند الشدائد، وهم يدعون معه في حال الرخاء غيره. القرطبي:٨/٤١٢.\nمن خلال الآية بين تناقض المشركين في استغاثتهم.\nأَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ\n﴿أَوۡ يَلۡبِسَكُمۡ شِيَعًا﴾: قيل: يجعلكم فرقًا يقاتل بعضكم بعضًا؛ وذلك بتخليط أمرهم، وافتراق أمرائهم على طلب الدنيا، وهو معنى قوله: ﴿وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ﴾ أي: بالحرب، والقتل في الفتنة. القرطبي:٨/٤١٤.\nكيف تكون العقوبة بلبس بعض المجتمع ببعض؟\nوَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nإن أنساك الشيطان النهي عن مجالستهم فلا تقعد بعد أن تذكر النهي. ابن جزي:١/٢٧٤.\nما نصيحتك لمن يجلس مع من يخوض في آيات الله بحجة الفكر والوعي؟\nوَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nمن خاض في آيات الله تُركت مجالسته وهُجِر؛ مؤمنًا كان أو كافرًا. القرطبي:٨/٤١٩.\nما موقفنا ممن يطرح البدع والشبهات؟\nوَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nنسيان الخير يكون من الشيطان؛ كما قال تعالى: ﴿وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ﴾. ابن تيمية:٣/٣٢.\nكيف ينسى العبد الخير؟"],[136,"§الأنعام\nwords\nتُبسَلَتُرتَهَنَ، وَتُحبَسَ.\nتَعدِلتَفتَدِ.\nأُبسِلُواارتُهِنُوا بِذُنُوبِهِم.\nحَمِيمٍمَاءٍ بَالِغِ الحَرَارَةِ.\nاستَهوَتهُهَوَت بِهِ؛ فَأَضَلَّتهُ.\nالصُّورِالقَرنِ الَّذِي يَنفُخُ فِيهِ إِسرَافِيلُ -عليه السلام-.\ndeeds\nحدد مجلس لهو تعودت عليه، واستبدل به مجلسًا مفيدًا.\nأرسل هذه الآية إلى بعض الذين يدعون الأموات.\nاستعذ بالله تعالى أن يستهويك الشيطان فيضلك عن سبيله، واسأل الله الثبات على دينه حتى تلقاه.\nguid\nإذا قام الإنسان بالأمر بالمعروف والنهي عن المنكر، ثم أعرض عن أصحاب المعاصي والكبائر وما يخوضون فيه؛ فلا إثم عليه.\nاحذر أن تجعل الدين مجالًا للطرائف واللهو والعبث؛ فشأن الدين عند الله عظيم.\nمن أنفع الوسائل في الدعوة إلى الله: الحديث عن القرآن وآياته.\nrefl\nوَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ ٦٩\nوفي هذا دليل على أنه ينبغي أن يستعمل المُذَكِّرُ من الكلام ما يكون أقربَ إلى حصول مقصود التقوى. السعدي:٢٦١.\nما الهدف الذي يجب أن يجعله الداعية أمامه حال تذكيره للناس؟\nوَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nأي: لا تعلق قلبك بهم؛ فإنهم أهل تعنت إن كنت مأمورًا بوعظهم... ومعنى ﴿لَعِبٌ وَلَهۡوٌۖ﴾ أي: استهزاء بالدين الذي دعوتهم إليه، وقيل: استهزءوا بالدين الذي هم عليه؛ فلم يعملوا به، والاستهزاء ليس مسوَّغًا في دين. القرطبي:٨/٤٢٣.\nكيف يكون اتخاذ دين الله تعالى لهوًا ولعبًا؟\nوَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nوذكر الحياة هنا له موقع عظيم؛ وهو أن همهم من هذه الدنيا هو الحياة فيها؛ لا ما يتكسب فيها من الخيرات التي تكون بها سعادة الحياة في الآخرة؛ أي: غرتهم الحياة الدنيا فأوهمتهم أن لا حياة بعدها. ابن عاشور:٧/٢٩٦.\nما فائدة ذكر الحياة في الآية الكريمة؟\nوَذَكِّرۡ بِهِۦٓ\nأي: ذَكَّر بالقرآن ما ينفع العباد أمرًا، وتفصيلًا، وتحسينًا له بذكر ما فيه من أوصاف الحسن، وما يضر العباد نهيًا عنه، وتفصيلًا لأنواعه. السعدي:٢٦١.\nما الطريقة المثلى لاستعمال القرآن في الدعوة وتذكير الناس؟\nوَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ\nأي: تحتبس عما فيه نجاتها في الدنيا والآخرة؛ فإن المعاصي قيد لصاحبها وحبس له، ومانع له من الجوَلان في فضاء التوحيد، وحائل بينه وبين أن يجني من ثمار الأعمال الصالحة؛ فهو محبوس هاهنا، وهناك في الآخرة. ابن تيمية:٣/٣٣.\nالمعاصي قيد لصاحبها، وضح ذلك من خلال الآية الكريمة.\nقُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ\nفمن الناس من يكون مع داعي الهدى في أموره كلها أو أغلبها، ومنهم من بالعكس من ذلك، ومنهم من يتساوى لديه الداعيان، ويتعارض عنده الجاذبان؛ وفي هذا الموضع تعرف أهل السعادة من أهل الشقاوة. السعدي:٢٦١-٢٦٢.\nما أنواع الناس أمام داعي الهدى؟ و من أيها ترجو أن تكون؟\nكَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ٧١\n﴿لَهُۥٓ أَصۡحَٰبٌ﴾: وهم رفقة يدعونه إلى الهدى، أي: إلى أن يهدوه إلى الطريق، يقولون له: ائتنا، وهو قد تاه وبعد عنهم فلا يجيبهم، وهذا كله تمثيل لمن ضل في الدين عن الهدى، وهو يدعى إلى الإسلام فلا يجيب. ابن جزي:١/٢٧٥.\nمن خلال هذه الآية وضح من الحيران؟"],[137,"§الأنعام\nwords\nجَنَّأَظلَمَ.\nالآفِلِينَالغَائِبِينَ.\nأَفَلَغَابَ.\nحَنِيفًامَائِلًا عَنِ الشِّركِ إِلَى التَّوحِيدِ.\ndeeds\nانكر منكرًا -ولو كان ذلك لأقرب قريب- وقدم النصح له؛ ولكن بأسلوب حكيم يرغبه في الاستجابة.\nسل الله تعالى أن تكون من الموقنين.\nأرسل رسالة تناصح فيها عباد القبور وتذكرهم بهذه الآية العظيمة.\nguid\nتفضل الله بالهداية على من يشاء.\nالحرص على بلوغ رتبة اليقين، وأنه من أشرف المراتب وأعزها، ومن أسباب الوصول إليها التفكر والنظر في الآيات.\nأكثر الناس فزعًا وخوفًا هم أهل الشرك، وأكثرهم أمنًا هم أهل الإخلاص.\nrefl\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ ٧٤\nوليس في ذلك ما ينافي البرور به؛ لأن المجاهرة بالحق دون سب ولا اعتداء لا ينافي البرور. ابن عاشور:٧/٣١٤.\nهل في أسلوب إبراهيم -عليه السلام- الوارد في الآية ما ينافي البر بالوالدين؟ وضح ذلك.\nفَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ٧٦\nذلك أن أصل العبادة هي المحبة، وأن الشرك فيها أصل الشرك؛ كما ذكره الله في قصة إمام الحنفاء إبراهيم الخليل؛ حيث قال: (فلما جن عليه الليل رأى كوكبًا قال هذا ربي فلما أفل قال لا أحب الآفلين). ابن تيمية:٣/٣٤.\nالمحبة أصل في العبادة، جعلها الجهلة أصلًا في الشرك، بين ذلك من الآية الكريمة.\nقَالَ هَٰذَا رَبِّيۖ\nأي: على وجه التَنَزُّل مع الخصم؛ أي: هذا ربي، فهَلُمَّ ننظر هل يستحق الربوبية؟! وهل يقوم لنا دليلٌ على ذلك؟! فإنه لا ينبغي لعاقل أن يتخذ إلهه هواه بغير حجة ولا برهان. السعدي:٢٦٢.\nما وجه وصفِ إبراهيم الكوكبَ بأنه ربُّه؟\nفَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ٧٦\nأي: الذي يغيب ويختفي عَمَّن عبده؛ فإن المعبود لا بُدَّ أن يكون قائمًا بمصالح من عبده، وَمُدَبِّرًا له في جميع شؤونه، فأما الذي يمضي وقتٌ كثيرٌ وهو غائبٌ فمن أين يستحق العبادة؟! وهل اتخاذه إلهًا إلا من أَسفَهِ السَّفَهِ، وأبطل الباطل؟! السعدي:٢٦٢.\nلماذا لا يستحق العبادة من كان يأفل ويغيب عن معبوده؟\nقَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ٧٧\nالأنبياء لم يزالوا يسألون الله تعالى الثبات على الإيمان، وكان إبراهيم يقول: ﴿وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ﴾ [إبراهيم: ٣٥]. البغوي:٢/٤١.\nبيّن ما يدل على حرص الأنبياء -عليهم السلام- على الثبات على الدين.\nإِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ٧٩\nإني وجهت وجهي في عبادتي إلى الذي خلق السماوات والأرض، الدائم الذي يبقى ولا يفنى، ويحيي ويميت، لا إلى الذي يفنى ولا يبقى، ويزول ولا يدوم، ولا يضر ولا ينفع. الطبري:١١/٤٨٧.\nما أسباب وجوب عبادة الله وعدم عبادة غيره؟\nوَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ ٨١ ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ ٨٢\nأي كيف أخاف أمواتًا وأنتم لا تخافون الله القادر على كل شيء... ﴿فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ﴾ أي: من عذاب الله؛ الموحد أم المشرك؟ فقال الله قاضيًا بينهم: ﴿ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ﴾ أي بشرك. القرطبي:٨/٤٤٤.\nمن الجهل أن تخاف من الأموات أكثر من الله، وضح ذلك من الآية."],[138,"§الأنعام\nwords\nيَلبِسُوايَخلِطُوا.\nوَاجتَبَينَاهُماصطَفَينَاهُم.\nاقتَدِهاقتَدِ وَاتَّبِـع.\ndeeds\nاقرأ تفسير هذه الآية بتدبر، ثم استخرج ثلاثًا مما اشتملت عليه من الفوائد.\nحدد ثلاث مسائل شرعية أشكلت عليك، ثم اتصل بأحد العلماء، واسأله عنها، وليكن هذا منهجًا لك فيما أشكل عليك؛ فرفعتك في الدنيا والآخرة على قدر علمك.\nحدد ثلاثًا من صفات الأنبياء واقتد بهم فيها.\nguid\nتحقيق التوحيد الخالص لله -سبحانه وتعالى- أمانٌ من كل خوفٍ في الدنيا والآخرة.\nخير ما يعطى المرء في هذه الحياة: الهداية إلى الصراط المستقيم.\nالأنبياء لو حصل منهم الشرك لبطلت أعمالهم؛ فكيف بمن هو دونهم.\nrefl\nوَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ\nفجزينا إبراهيم -عليه السلام- على طاعته إيانا، وإخلاصه توحيد ربه، ومفارقته دين قومه المشركين بالله، بأن رفعنا درجته في عليين، وآتيناه أجره في الدنيا، ووهبنا له أولادًا خصصناهم بالنبوة، وذرية شرفناهم منا بالكرامة، وفضلناهم على العالمين. الطبري:١١/٥٠٧.\nمن ترك شيئًا لله عوضه الله خيرًا، وضح ذلك من الآية.\nوَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ\nفإن العلم يرفع الله به صاحبه فوق العباد درجات؛ خصوصًا العالم العامل المعلم؛ فإنه يجعله الله إمامًا للناس بحسب حاله؛ تُرمَقُ أفعاله، وتُقتفى آثاره، ويُستضاء بنوره، ويُمشى بعلمه. السعدي:٢٦٣.\nما سبب رفع إبراهيم على قومه درجات؟\nنَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ٨٣\nأي: نرفع درجات من نشاء بالعلم، والفهم، والفضيلة، والعقل؛ كما رفعنا درجات إبراهيم حتى اهتدى، وحاج قومه في التوحيد. البغوي:٢/٤١.\nكيف يُرفع العبد درجات؟\nوَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ٨٤\nوكان هذا مجازاة لإبراهيم -عليه السلام- حين اعتزل قومه وتركهم، ونزح عنهم، وهاجر من بلادهم ذاهبًا إلى عبادة الله في الأرض، فعوضه الله -عز وجل- عن قومه وعشيرته بأولاد صالحين من صلبه على دينه؛ لتقر بهم عينه. ابن كثير:٢/١٤٧.\nكيف كان الأولاد جزاء لإحسان إبراهيم -عليه السلام-؟\nوَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ٨٨\n﴿وَلَوۡ أَشۡرَكُواْ﴾ على الفرض والتقدير ﴿لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ﴾؛ فإن الشرك محبط للعمل، موجب للخلود في النار، فإذا كان هؤلاء الصفوة الأخيار لو أشركوا -وحاشاهم- لحبطت أعمالهم، فغيرهم أولى. السعدي:٢٦٤.\nالشرك محبط للعمل ولو وقع من كبار العباد والصالحين، وضح ذلك من الآية.\nوَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ٨٨\nأي: لو عبدوا غيري لحبطت أعمالهم، ولكني عصمتهم. القرطبي:٨/٤٥١.\nما جزاء من أشرك بالله تعالى وكانت له أعمال صالحة؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ\nأي: امش أيها الرسول الكريم خلف هؤلاء الأنبياء الأخيار، واتبع ملتهم، وقد امتثل؛ فاهتدى بهدي الرسل قبله، وجمع كل كمال فيهم؛ فاجتمعت لديه فضائل وخصائص فاق بها جميع العالمين، وكان سيد المرسلين وإمام المتقين، صلوات الله وسلامه عليه وعليهم أجمعين. السعدي:٢٦٤.\nكيف تدل هذه الآية على أفضلية رسولنا الكريم -صلى الله عليه وسلم- على جميع الرسل؟"],[139,"§الأنعام\nwords\nغَمَرَاتِأَهوَالِ.\nخَوَّلنَاكُممَلَّكنَاكُم مِن مَتَاعِ الدُّنيَا.\nتَقَطَّعَ بَينَكُمزَالَ تَوَاصُلُكُم.\ndeeds\nتذكر ثلاث بركات للقرآن الكريم عليك أو على الأمة.\nاذهب اليوم إلى الصلوات في أول وقتها، وأدها بأركانها وشروطها، كما أمرك الله تعالى.\nاجلس مع نفسك جلسة محاسبة ومعاتبة؛ تقارن فيها بين حسناتك الكبيرة وسيئاتك الكبيرة فيما مضى من عمرك، وتتذكر فيها يوم العرض على الله.\nguid\nتأمل في حلم الله تعالى على عباده؛ حيث يسمع الأذى منهم، وتكذيب رسله وأوليائه، ومع هذا لا يعاجلهم بعقوبته؛ لعلهم يؤمنوا ويرجعوا.\nأقبل على كتاب الله تعالى متدبرًا متعظًا بما فيه، حتى تنال من بركته وخيره.\nكل ما تجمعه في هذه الدنيا سيفنى ويذهب، ثم تذهب أنت فردًا بين يدي الله تعالى.\nrefl\nوَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ\n﴿وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ﴾ أي: ما عرفوه حق معرفته في اللطف بعباده والرحمة لهم؛ إذ أنكروا بعثه للرسل، وإنزاله للكتب. والقائلون هم اليهود؛ بدليل ما بعده، وإنَّما قالوا ذلك مبالغة في إنكار نبوة محمد -صلى الله عليه وسلم-. ابن جزي:١/٢٧٨.\nما علامة تقدير الله -عز وجل- حق قدره؟\nوَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ\nقال ابن عباس في رواية الوالبي عنه: \"هذه في الكفار، فأما من آمن أن الله على كل شيء قدير فقد قدر الله حق قدره\". ابن تيمية:٣/٥٣.\nمن الذي يقدر الله حق قدره؟\nوَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ\nومن هذا النمط من أعرض عن الفقه والسُّنن وما كان عليه السلف من السَّنن؛ فيقول: وقع في خاطري كذا، أو أخبرني قلبي بكذا، فيحكمون بما يقع في قلوبهم ويغلب عليهم من خواطرهم... فيستغنون بها عن أحكام الشرائع الكليات، ويقولون: هذه الأحكام الشرعية العامة إنَّما يحكم بها على الأغبياء والعامة، وأمَّا الأولياء وأهل الخصوص فلا يحتاجون لتلك النصوص. القرطبي:٨/٤٥٨.\nهل يدخل في الكذب على الله تعالى اعتبار الخواطر القلبية والرؤى المنامية مصدرًا من مصادر التشريع؟\nوَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ\nإنَّما كان هذا أظلم الخلق؛ لأن فيه من الكذب، وتغيير الأديان -أصولها وفروعها-، ونسبة ذلك إلى الله؛ ما هو من أكبر المفاسد. السعدي:٢٦٥.\nلماذا كان المفتري على الله كذبًا من أظلم الخلق؟\nوَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ ٩٣\n﴿وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ﴾: بالعذاب والضرب؛ يضربون وجوههم وأدبارهم، وقيل: بقبض الأرواح. (أخرجوا) أي: يقولون: أخرجوا (أنفسكم) أي: أرواحكم كرهًا؛ لأن نفس المؤمن تنشط للقاء ربه، ونفس الكافر تكره ذلك. والجواب محذوف؛ يعني: لو تراهم في هذه الحال لرأيت عجبًا. البغوي:٢/٤٧.\nما الفرق بين خروج روح المؤمن وخروج روح الكافر عند الموت؟\nوَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ\nوالمعنى: جئتمونا واحدًا واحدًا؛ كل واحد منكم منفردًا، بلا أهل، ولا مال، ولا ولد، ولا ناصر ممن كان يصاحبكم في الغي. القرطبي:٨/٤٦١.\nلماذا اعتبرت أموال الإنسان وأهله وأولاده من زينة الدنيا الفانية؟\nوَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ\nالجميع عبيد لله، والله مالكهم والمستحق لعبادتهم، فشركهم في العبادة وصرفها لبعض العبيد تنزيل لهم منزلة الخالق المالك، فيوبخون يوم القيامة. السعدي:٢٦٥.\nمن خلال الآية: بيّن حسرة من يعبدون الصالحين يوم القيامة وندامتهم."],[140,"§الأنعام\nwords\nتُؤفَكُونَتُصرَفُونَ عَنِ الحَقِّ.\nقِنوَانٌ دَانِيَةٌعُذُوقٌ قَرِيبَةُ التَّنَاوُلِ.\nوَيَنعِهِنُضجِهِ، وَبُلُوغِهِ حِينَ يَبلُغُ.\nوَخَرَقُوااختَلَقُوا وَافتَرَوا لَهُ سُبحَانَهُ.\ndeeds\nاذكر مثالًا لحي أخرجه الله من ميت، وميت أخرجه الله من حي، وتأمل قدرة الله تعالى.\nاقرأ عن أهمية التقويم القمري للعبادات، واجتهد في حفظ شهوره؛ حتى تتابع العبادات.\nنم الليلة مبكرًا كما هي الفطرة والسنة.\nguid\nمن فتح قلبَه وعقلَه للقرآن كان جديرًا بأن يدرك مقاصد الآيات، بخلاف من أغلق قلبه وعقله دونه.\nما نأكل من طعام يستحق أن نتأمل في بديع صنع الله سبحانه فيه، وكيفية اختلاف طعمه وألوانه.\nإذا سمعت قول من يفتري الكذب على الله تعالى فسبح ربك، ونزهه عما يقول الظالمون الملحدون.\nrefl\nإِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ٩٥\nعَدّ من عجائب صنعه ما يعجز عن أدنى شيء منه آلهتهم. القرطبي:٨/٤٦٥.\nما الحكمة في تعداد ذكر عجائب صنع الله تعالى في الآية الكريمة؟\nيُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ٩٥ فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ\nفَبَيَّنَ تعالى قدرته على خلق الأشياء المتضادة المختلفة، الدَّالَّةِ على كمال عظمته. ابن كثير:٢/١٥٠.\nعلى ماذا تدل قدرة الله تعالى على خلق الأشياء المتضادة؟\nوَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٩٧\nودلت هذه الآية ونحوها على مشروعية تعلم سير الكواكب ومحالها، الذي يُسَمَّى علمَ التسيير؛ فإنه لا تتم الهداية ولا تمكن إلا بذلك. السعدي:٢٦٦.\nما المشروع في علم النجوم؟ وما المحرم من ذلك؟\nقَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ ٩٨\nأي: لأهل العلم والمعرفة؛ فإنهم الذين يوجه إليهم الخطاب، ويطلب منهم الجواب، بخلاف أهل الجهل والجفاء، المعرضين عن آيات الله وعن العلم الذي جاءت به الرسل؛ فإن البيان لا يفيدهم شيئًا، والتفصيل لا يزيل عنهم ملتبسًا، والأيضَاح لا يكشف لهم مشكلًا. السعدي:٢٦٦.\nلماذا خُصَّ أهل العلم بتفصيل الآيات دون غيرهم؟\nوَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ\nوخص الدانية بالذكر؛ لأن من الغرض في الآية ذكر القدرة، والامتنان بالنعمة، والامتنان فيما يقرب متناوله أكثر. القرطبي:٨/٤٧٢.\nلماذا خص عذوق النخل الدانية بالذكر في هذه الآية؟\nٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٩٩\nنظر الاعتبار، لا نظر الإبصار المجرد عن التفكر. القرطبي:٨/٤٧٢.\nما النظر المأمور به في هذه الآية الكريمة؟\nإِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٩٩\nفإن المؤمنين يحملهم ما معهم من الإيمان على العمل بمقتضياته ولوازمه؛ التي منها التفكر في آيات الله، والاستنتاج منها ما يراد منه، وما تدل عليه عقلًا، وفطرةً، وشرعًا. السعدي:٢٦٧.\nلماذا خص المؤمنين بالإفادة من آيات الله دون غيرهم؟"],[141,"§الأنعام\nwords\nنُصَرِّفُنُبَيِّنُ.\nدَرَستَتَعَلَّمتَ.\nعَدوًااعتِدَاءً.\nيَعمَهُونَيَتَحَيَّرُونَ.\ndeeds\nاجمع آيات تتكلم عن موضوع يشغل ذهنك، ثم اقرأ تفسيرها، أو اسأل عن معناها.\nقل: \"اللهم إني أعوذ بك أن يزين لي سوء عملي\".\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nguid\nالزم الوحي من الكتاب والسنة الصحيحة، ولا تستبدل بهما شيئًا آخر.\nإياك أن تأتي في دعوتك ما ينفر مخالفك من دعوة أهل السنة والجماعة وطريقتهم، بل التزم الحكمة؛ فهي من أقوى أسلحة الداعية إلى الله تعالى.\nالإعراض عن الدين قد يُعاقب عليه المعرض بصرفه عن الهدى والدين دائمًا، فاحذر من ذلك.\nrefl\nذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ١٠٢\n﴿ٱللَّهُ رَبُّكُمۡۖ﴾ أي: المألوه المعبود، الذي يستحق نهاية الذل، ونهاية الحب؛ الرب الذي ربى جميع الخلق بالنعم، وصرف عنهم صنوف النقم. السعدي:٢٦٨.\nما معنى كلمة (الرب)؟ وماذا يترتب على ذلك؟\nوَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ١٠٢\nوكالته تعالى على الأشياء ليست من جنس وكالة الخلق؛ فإن وكالتهم وكالة نيابة، والوكيل فيها تابع لموكله، وأمَّا الباري -تبارك وتعالى- فوكالته من نفسه لنفسه، متضمنة لكمال العلم، وحسن التدبير والإحسان فيه، والعدل؛ فلا يمكن لأحدٍ أن يستدرك على الله، ولا يرى في خلقه خللًا ولا فطورًا، ولا في تدبيره نقصًا وعيبًا. السعدي:٢٦٨.\nما الفرق بين وكالة الله على الأشياء، ووكالة الناس عليها؟\nلَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ١٠٣\nنفى الإدراك الذي هو الإحاطة -كما قاله أكثر العلماء- ولم ينف مجرد الرؤية؛ لأن المعدوم لا يرى، وليس في كونه \"لا يرى\" مدح؛ إذ لو كان كذلك لكان المعدوم ممدوحًا، وإنَّما المدح في كونه لا يحاط به وإن رُئي؛ كما أنه لا يُحاط به وإن عُلم؛ فكما أنه إذا عُلم لا يحاط به علمًا، فكذلك إذا رُئي لا يحاط به رؤيةً. ابن تيمية:٣/٧٨-٧٩.\nكيف تستدل بالآية على إثبات رؤية الله يوم القيامة لا نفيها؟\nٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ١٠٦\nأي: لا تشغل قلبك وخاطرك بهم، بل اشتغل بعبادة الله. القرطبي:٨/٤٩٠.\nما الأمر الذي ينبغي أن تشغل به نفسك في هذه الحياة؟\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nنهى سبحانه المؤمنين أن يسبوا أوثانهم؛ لأنه علم أنهم إذا سبوها نفر الكفار، وازدادوا كفرًا. القرطبي:٨/٤٩١.\nلماذا نهى الله تعالى المؤمنين عن سب آلهة الكفار وأوثانهم؟\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nوفي هذه الآية الكريمة دليل للقاعدة الشرعية؛ وهي: أن الوسائل تعتبر بالأمور التي توصل إليها، وأن وسائل المحرم -ولو كانت جائزة- تكون محرمة إذا كانت تفضي إلى الشر. السعدي:٢٦٩.\nاستنبط العلماء من الآية قاعدة شرعية عظيمة، فما هي؟\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nفمتى كان الكافر في منعة، وخيف أن يسب الإسلام أو النبي -صلى الله عليه وسلم- والله -عز وجل-؛ فلا يحل للمسلم أن يسب دينهم، ولا صلبانهم، ولا يتعرض ما يؤدي إلى ذلك، أو نحوه. ابن عطية:٢/٣٣٢.\nمتى تقتضي الحكمة عدم سب آلهة الكفار؟"]])